5	@MainActor
6	final class AppState: ObservableObject {
7	    @Published var connectionStatus: ConnectionStatus = .disconnected
8	    @Published var notifications: [BridgeNotification] = []
9	    @Published var workspaces: [Workspace] = []
10	    @Published var currentWorkspaceID: String?
11	    @Published var surfaces: [Surface] = []
12	    @Published var panes: [Pane] = []
13	    @Published var isPairingPresented = false
14	    // Tracks the last surface explicitly focused by the user; used when surface.list
15	    // doesn't return is_focused and pane.list is unavailable.
