37	    private func scheduleLocalNotification(_ n: BridgeNotification) {
38	        let center = UNUserNotificationCenter.current()
39	        let content = UNMutableNotificationContent()
40	        content.title = n.title
41	        if let subtitle = n.subtitle { content.subtitle = subtitle }
42	        if let body = n.body { content.body = body }
43	        content.sound = .default
44	
45	        let request = UNNotificationRequest(
46	            identifier: n.id,
47	            content: content,
48	            trigger: nil // deliver immediately
49	        )
50	        center.add(request)
51	    }
