55	    func handlePairingURL(_ url: URL) {
56	        guard url.scheme == "cmux-bridge",
57	              url.host == "pair",
58	              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
59	              let host = components.queryItems?.first(where: { $0.name == "host" })?.value,
60	              let portStr = components.queryItems?.first(where: { $0.name == "port" })?.value,
61	              let port = Int(portStr),
62	              let token = components.queryItems?.first(where: { $0.name == "token" })?.value
63	        else { return }
64	
65	        let tailscaleHost = components.queryItems?.first(where: { $0.name == "tailscale_host" })?.value
66	        let credentials = PairingCredentials(host: host, port: port, token: token, tailscaleHost: tailscaleHost)
67	        try? pairingStore.save(credentials)
68	        connect(to: credentials)
69	        isPairingPresented = false
70	    }
