108	
109	    func selectWorkspace(_ id: String) {
110	        send(method: "workspace.select", params: ["workspace_id": id]) { [weak self] _ in
111	            self?.currentWorkspaceID = id
112	            self?.localFocusedSurfaceID = self?.lastFocusedSurface[id]
