139	    func cycleSurface() {
140	        let list = surfaces
141	        guard !list.isEmpty else { return }
142	        let currentIndex = list.firstIndex(where: { $0.id == focusedSurfaceID }) ?? -1
143	        let nextIndex = (currentIndex + 1) % list.count
144	        focusSurface(list[nextIndex].id)
145	    }
