148	        let list = surfaces
149	        guard !list.isEmpty else { return }
150	        let currentIndex = list.firstIndex(where: { $0.id == focusedSurfaceID }) ?? 0
151	        let prevIndex = (currentIndex - 1 + list.count) % list.count
152	        focusSurface(list[prevIndex].id)
153	    }
