169	    func cycleTabInFocusedPane() {
170	        guard let focused = panes.first(where: { $0.isFocused }),
171	              focused.surfaceIDs.count > 1 else { return }
172	        let currentIndex = focused.surfaceIDs.firstIndex(of: focused.focusedSurfaceID ?? "") ?? -1
173	        let nextIndex = (currentIndex + 1) % focused.surfaceIDs.count
174	        focusSurface(focused.surfaceIDs[nextIndex])
