185	    func readSurfaceText(_ surfaceID: String, lines: Int = 50, scrollback: Bool = false) {
186	        var params: [String: Any] = ["surface_id": surfaceID]
187	        if scrollback {
188	            params["scrollback"] = true
189	        } else {
190	            params["lines"] = lines
191	        }
192	        if let wsID = currentWorkspaceID {
193	            params["workspace_id"] = wsID
194	        }
195	        send(method: "surface.read_text", params: params) { [weak self] result in
196	            if let text = result["text"] as? String {
197	                // Trim trailing whitespace per line and remove blank trailing lines
198	                let trimmed = text
199	                    .split(separator: "\n", omittingEmptySubsequences: false)
200	                    .map { $0.replacingOccurrences(of: "\\s+$", with: "", options: .regularExpression) }
201	                    .joined(separator: "\n")
202	                    .replacingOccurrences(of: "\\n+$", with: "", options: .regularExpression)
203	                self?.surfaceContent[surfaceID] = trimmed
204	            }
205	        }
206	    }
207	
208	    func readBrowserURL(_ surfaceID: String) {
209	        send(method: "browser.url.get", params: ["surface_id": surfaceID]) { [weak self] result in
210	            if let url = result["url"] as? String {
211	                self?.browserURLs[surfaceID] = url
212	            }
213	        }
214	    }
