216	    func createWorkspace(name: String? = nil) {
217	        var params: [String: Any] = [:]
218	        if let name { params["name"] = name }
219	        send(method: "workspace.create", params: params) { [weak self] _ in
220	            self?.refreshWorkspaces()
221	            self?.refreshSurfaces()
222	        }
223	    }
224	
225	    func closeWorkspace(_ id: String) {
226	        send(method: "workspace.close", params: ["workspace_id": id]) { [weak self] _ in
227	            self?.lastFocusedSurface.removeValue(forKey: id)
228	            self?.refreshWorkspaces()
229	            // Select next available workspace
230	            if self?.currentWorkspaceID == id {
231	                if let next = self?.workspaces.first(where: { $0.id != id }) {
232	                    self?.selectWorkspace(next.id)
233	                }
234	            }
235	        }
236	    }
