238	    func splitSurface(direction: String, surfaceID: String? = nil) {
239	        let previousIDs = Set(surfaces.map(\.id))
240	        var params: [String: Any] = ["direction": direction]
241	        if let surfaceID { params["surface_id"] = surfaceID }
242	        send(method: "surface.split", params: params) { [weak self] _ in
243	            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
244	        }
245	    }
246	
247	    func createSurface(type: String = "terminal") {
248	        let previousIDs = Set(surfaces.map(\.id))
249	        send(method: "surface.create", params: ["type": type]) { [weak self] _ in
250	            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
251	        }
252	    }
253	
254	    func closeSurface(_ surfaceID: String) {
255	        send(method: "surface.close", params: ["surface_id": surfaceID]) { [weak self] _ in
256	            self?.refreshSurfaces()
257	        }
258	    }
259	
260	    func clearNotifications() {
261	        send(method: "notification.clear", params: [:]) { [weak self] _ in
262	            self?.notifications = []
263	        }
264	    }
265	
266	    func refreshWorkspaces() {
267	        send(method: "workspace.list", params: [:]) { [weak self] result in
268	            if let list = result["workspaces"] as? [[String: Any]] {
269	                self?.workspaces = list.compactMap(Workspace.init)
270	            }
271	        }
272	        send(method: "workspace.current", params: [:]) { [weak self] result in
273	            self?.currentWorkspaceID = result["id"] as? String
274	        }
275	    }
276	
277	    func refreshSurfaces(workspaceID: String? = nil) {
278	        var params: [String: Any] = [:]
279	        if let id = workspaceID ?? currentWorkspaceID {
280	            params["workspace_id"] = id
281	        }
282	        send(method: "surface.list", params: params) { [weak self] result in
283	            if let list = result["surfaces"] as? [[String: Any]] {
284	                self?.surfaces = list.compactMap(Surface.init)
285	                // Validate remembered surface still exists
286	                if let localID = self?.localFocusedSurfaceID,
287	                   self?.surfaces.contains(where: { $0.id == localID }) == false {
288	                    self?.localFocusedSurfaceID = nil
289	                }
290	                // Auto-select first surface if nothing is focused
291	                if self?.focusedSurfaceID == nil, let first = self?.surfaces.first {
292	                    self?.localFocusedSurfaceID = first.id
293	                }
294	            }
295	        }
296	    }
297	
298	    private func refreshSurfacesAndFocusNew(previousIDs: Set<String>) {
299	        var params: [String: Any] = [:]
300	        if let id = currentWorkspaceID {
301	            params["workspace_id"] = id
302	        }
303	        send(method: "surface.list", params: params) { [weak self] result in
304	            guard let self else { return }
305	            if let list = result["surfaces"] as? [[String: Any]] {
306	                self.surfaces = list.compactMap(Surface.init)
307	                if let newSurface = self.surfaces.first(where: { !previousIDs.contains($0.id) }) {
308	                    self.focusSurface(newSurface.id)
309	                } else if self.focusedSurfaceID == nil, let first = self.surfaces.first {
310	                    self.localFocusedSurfaceID = first.id
311	                }
312	            }
313	        }
314	    }
315	
316	    func refreshPanes() {
317	        var params: [String: Any] = [:]
318	        if let id = currentWorkspaceID {
319	            params["workspace_id"] = id
320	        }
321	        send(method: "pane.list", params: params) { [weak self] result in
322	            if let list = result["panes"] as? [[String: Any]] {
323	                self?.panes = list.compactMap(Pane.init)
324	            }
325	        }
326	    }
