328	    // MARK: - Helpers
329	
330	    var focusedSurfaceID: String? {
331	        // Prefer pane-derived focus, then surface.is_focused, then local tracking
332	        panes.first(where: { $0.isFocused })?.focusedSurfaceID
333	            ?? surfaces.first(where: { $0.isFocused })?.id
334	            ?? localFocusedSurfaceID
335	    }
336	
337	    var currentWorkspaceSurfaces: [Surface] {
338	        guard let wsID = currentWorkspaceID else { return surfaces }
339	        return surfaces.filter { $0.workspaceID == wsID }
340	    }
341	
342	    func surfaceTitle(for id: String) -> String {
343	        surfaces.first(where: { $0.id == id })?.title ?? ""
344	    }
345	
346	    func hasNotification(for pane: Pane) -> Bool {
347	        notifications.contains { n in
348	            guard let sid = n.surfaceID else { return false }
349	            return pane.surfaceIDs.contains(sid)
350	        }
351	    }
352	
353	    func hasNotification(for surface: Surface) -> Bool {
354	        notifications.contains { $0.surfaceID == surface.id }
355	    }
356	
357	    func clearNotificationsForFocusedSurface() {
358	        guard let focusedID = focusedSurfaceID else { return }
359	        notifications.removeAll { $0.surfaceID == focusedID }
360	    }
361	
362	    // MARK: - Private helpers
363	
364	    private func send(
365	        method: String,
366	        params: [String: Any],
367	        completion: (([String: Any]) -> Void)? = nil
368	    ) {
369	        client?.send(method: method, params: params, completion: completion)
370	    }
371	}
