373	// MARK: - BridgeClientDelegate
374	
375	extension AppState: BridgeClientDelegate {
376	    func clientDidConnect(_ client: BridgeClient) {
377	        connectionStatus = .connected
378	        refreshWorkspaces()
379	        refreshSurfaces()
380	        refreshPanes()
381	    }
382	
383	    func clientDidDisconnect(_ client: BridgeClient, error: Error?) {
384	        connectionStatus = .reconnecting
385	    }
386	
387	    func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage) {
388	        switch message {
389	        case .connected(let payload):
390	            connectionStatus = .connected(cmuxConnected: payload.cmuxConnected)
391	        case .notificationCreated(let n):
392	            notifications.insert(n, at: 0)
393	            print("[Notification] id=\(n.id) surfaceID=\(n.surfaceID ?? "nil") workspaceID=\(n.workspaceID ?? "nil") title=\(n.title)")
394	            print("[Notification] surface IDs: \(surfaces.map(\.id))")
395	            scheduleLocalNotification(n)
396	        case .notificationCleared:
397	            notifications = []
398	        case .cmuxConnected:
399	            connectionStatus = .connected(cmuxConnected: true)
400	            refreshWorkspaces()
401	            refreshSurfaces()
402	            refreshPanes()
403	        case .cmuxDisconnected:
404	            connectionStatus = .connected(cmuxConnected: false)
405	            panes = []
406	        case .commandResponse:
407	            break
408	        }
409	    }
410	}
