417	              let stored = try? pairingStore.load() else { return }
418	        if let match = candidates.first(where: { $0.host == stored.host && $0.port == stored.port }) {
419	            connect(to: PairingCredentials(host: match.host, port: match.port, token: stored.token, tailscaleHost: stored.tailscaleHost))
420	        }
421	    }
