426	struct BridgeNotification: Identifiable, Decodable {
427	    let id: String
428	    let title: String
429	    let subtitle: String?
430	    let body: String?
431	    let workspaceID: String?
432	    let surfaceID: String?
433	    let isRead: Bool?
434	
