443	struct Workspace: Identifiable {
444	    let id: String
445	    let name: String
446	
447	    init?(_ dict: [String: Any]) {
448	        guard let id = dict["id"] as? String else { return nil }
449	        self.id = id
450	        self.name = (dict["name"] as? String) ?? id
