454	struct Surface: Identifiable {
455	    let id: String
456	    let title: String
457	    let type: String
458	    let workspaceID: String?
459	    let isFocused: Bool
460	
461	    var isBrowser: Bool { type == "browser" }
462	
463	    init?(_ dict: [String: Any]) {
464	        guard let id = dict["id"] as? String else { return nil }
465	        self.id = id
466	        self.type = (dict["type"] as? String) ?? "terminal"
467	        self.title = (dict["title"] as? String) ?? self.type
468	        self.workspaceID = dict["workspace_id"] as? String
469	        self.isFocused = dict["is_focused"] as? Bool ?? false
470	    }
471	}
472	
473	struct Pane: Identifiable {
474	    let id: String
475	    let pixelFrame: CGRect
476	    let containerFrame: CGSize
477	    let surfaceIDs: [String]
478	    let focusedSurfaceID: String?
479	    let isFocused: Bool
480	
481	    var normalizedFrame: CGRect {
482	        guard containerFrame.width > 0, containerFrame.height > 0 else {
483	            return CGRect(x: 0, y: 0, width: 1, height: 1)
484	        }
485	        return CGRect(
486	            x: pixelFrame.origin.x / containerFrame.width,
487	            y: pixelFrame.origin.y / containerFrame.height,
488	            width: pixelFrame.size.width / containerFrame.width,
489	            height: pixelFrame.size.height / containerFrame.height
490	        )
491	    }
492	
493	    init?(_ dict: [String: Any]) {
494	        guard let id = dict["id"] as? String else { return nil }
495	        self.id = id
496	
497	        if let pf = dict["pixel_frame"] as? [String: Any] {
498	            let x = (pf["x"] as? Double).map { CGFloat($0) } ?? 0
499	            let y = (pf["y"] as? Double).map { CGFloat($0) } ?? 0
500	            let w = (pf["width"] as? Double).map { CGFloat($0) } ?? 100
501	            let h = (pf["height"] as? Double).map { CGFloat($0) } ?? 100
502	            pixelFrame = CGRect(x: x, y: y, width: w, height: h)
503	        } else {
504	            pixelFrame = CGRect(x: 0, y: 0, width: 100, height: 100)
505	        }
506	
507	        if let cf = dict["container_frame"] as? [String: Any] {
508	            let w = (cf["width"] as? Double).map { CGFloat($0) } ?? 100
509	            let h = (cf["height"] as? Double).map { CGFloat($0) } ?? 100
510	            containerFrame = CGSize(width: w, height: h)
511	        } else {
512	            containerFrame = CGSize(width: 100, height: 100)
513	        }
514	
515	        surfaceIDs = dict["surface_ids"] as? [String] ?? []
516	        focusedSurfaceID = dict["focused_surface_id"] as? String
517	        isFocused = dict["is_focused"] as? Bool ?? false
518	    }
519	}
520	
521	enum ConnectionStatus: Equatable {
522	    case disconnected
523	    case connecting
524	    case reconnecting
525	    case connected(cmuxConnected: Bool = true)
526	
527	    static var connected: ConnectionStatus { .connected(cmuxConnected: true) }
528	
529	    var isConnected: Bool {
530	        if case .connected = self { return true }
531	        return false
532	    }
533	
534	    var label: String {
535	        switch self {
536	        case .disconnected: return "Disconnected"
537	        case .connecting: return "Connecting…"
538	        case .reconnecting: return "Reconnecting…"
539	        case .connected(let cmux):
540	            return cmux ? "Connected" : "Bridge connected (cmux offline)"
541	        }
542	    }
543	
544	    var color: String {
545	        switch self {
546	        case .connected(true): return "green"
547	        case .connected(false): return "yellow"
548	        case .reconnecting: return "yellow"
549	        case .connecting: return "yellow"
550	        case .disconnected: return "red"
551	        }
552	    }
553	}
