88	final class QuickActionState: ObservableObject {
89	    @Published var isOpen = false
90	    @Published var isFullscreen = false
91	    @Published var selectedIndex = 0
92	    @Published var currentSectionIndex = 0
93	    var actions: [QuickAction] = []
94	
95	    private static let canonicalOrder = ["Input", "Terminal", "Workspace", "AI"]
96	
97	    var sectionOrder: [String] {
98	        let present = Set(actions.map(\.section))
99	        return Self.canonicalOrder.filter { present.contains($0) }
100	    }
101	
102	    var currentSection: String {
103	        guard sectionOrder.indices.contains(currentSectionIndex) else { return sectionOrder[0] }
104	        return sectionOrder[currentSectionIndex]
105	    }
106	
107	    var currentSectionActions: [(Int, QuickAction)] {
108	        actions.enumerated().filter { $0.element.section == currentSection }.map { ($0.offset, $0.element) }
109	    }
110	
111	    func open(with actions: [QuickAction]) {
112	        self.actions = actions
113	        currentSectionIndex = 0
114	        selectedIndex = actions.firstIndex(where: { $0.section == sectionOrder[0] }) ?? 0
115	        isOpen = true
116	        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
117	    }
118	
119	    func dismiss() {
120	        isOpen = false
121	        actions = []
122	    }
123	
124	    func cycle() {
125	        let sectionItems = currentSectionActions
126	        guard !sectionItems.isEmpty else { return }
127	        if let currentPos = sectionItems.firstIndex(where: { $0.0 == selectedIndex }) {
128	            let nextPos = (currentPos + 1) % sectionItems.count
129	            selectedIndex = sectionItems[nextPos].0
130	        } else {
131	            selectedIndex = sectionItems[0].0
132	        }
133	        UISelectionFeedbackGenerator().selectionChanged()
134	    }
135	
136	    func nextSection() {
137	        currentSectionIndex = (currentSectionIndex + 1) % sectionOrder.count
138	        // Select first item in new section
139	        if let first = currentSectionActions.first {
140	            selectedIndex = first.0
141	        }
142	        UISelectionFeedbackGenerator().selectionChanged()
143	    }
144	
145	    func prevSection() {
146	        currentSectionIndex = (currentSectionIndex - 1 + sectionOrder.count) % sectionOrder.count
147	        if let first = currentSectionActions.first {
148	            selectedIndex = first.0
149	        }
150	        UISelectionFeedbackGenerator().selectionChanged()
151	    }
152	
153	    func execute() {
154	        guard actions.indices.contains(selectedIndex) else { return }
155	        actions[selectedIndex].action()
156	        UIImpactFeedbackGenerator(style: .light).impactOccurred()
157	        dismiss()
158	    }
159	}
