import Foundation

// MARK: - Bridge Provider

enum BridgeProvider: String, Codable, CaseIterable, Identifiable {
    case cmux
    case codex
    case t3code

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .cmux: return "cmux"
        case .codex: return "Codex"
        case .t3code: return "T3 Code"
        }
    }

    var description: String {
        switch self {
        case .cmux: return "Terminal multiplexer for AI coding agents"
        case .codex: return "OpenAI Codex CLI"
        case .t3code: return "T3 Code desktop app"
        }
    }

    var iconName: String {
        switch self {
        case .cmux: return "rectangle.split.3x1"
        case .codex: return "chevron.left.forwardslash.chevron.right"
        case .t3code: return "square.stack.3d.up"
        }
    }

    var defaultPort: Int {
        switch self {
        case .cmux: return 47821
        case .codex: return 0 // user-specified
        case .t3code: return 3773
        }
    }
}

// MARK: - Surface model

enum SurfaceKind: Equatable {
    case agent(AgentInfo)
    case terminal
    case browser
}

struct AgentInfo: Equatable {
    let agent: String  // "claude", "opencode", "aider", "codex"
    let agentStatus: AgentStatus
}

enum AgentStatus: String, Equatable {
    case idle
    case working
    case waitingApproval = "waiting_approval"
    case error
    case unknown
}

struct BridgeSurface: Identifiable, Equatable {
    let id: String
    let title: String
    let kind: SurfaceKind
    let isFocused: Bool
    let groupID: String?  // workspace ID, project ID, etc.

    var isAgent: Bool {
        if case .agent = kind { return true }
        return false
    }

    var isBrowser: Bool { kind == .browser }
    var isTerminal: Bool { kind == .terminal }
}

// MARK: - Session group (workspace, project, etc.)

struct SessionGroup: Identifiable {
    let id: String
    let name: String
}

// MARK: - Capabilities

struct BridgeCapabilities: OptionSet {
    let rawValue: Int

    static let sessionManagement    = BridgeCapabilities(rawValue: 1 << 0)
    static let terminalIO           = BridgeCapabilities(rawValue: 1 << 1)
    static let outputStreaming       = BridgeCapabilities(rawValue: 1 << 2)
    static let outputPolling         = BridgeCapabilities(rawValue: 1 << 3)
    static let structuredApprovals   = BridgeCapabilities(rawValue: 1 << 4)
    static let agentStatus           = BridgeCapabilities(rawValue: 1 << 5)
    static let fileDiffs             = BridgeCapabilities(rawValue: 1 << 6)
    static let gitOperations         = BridgeCapabilities(rawValue: 1 << 7)
    static let multiAgent            = BridgeCapabilities(rawValue: 1 << 8)
    static let terminalResize        = BridgeCapabilities(rawValue: 1 << 9)
    static let paneLayout            = BridgeCapabilities(rawValue: 1 << 10)
    static let surfaceSplit          = BridgeCapabilities(rawValue: 1 << 11)
    static let browserSurfaces       = BridgeCapabilities(rawValue: 1 << 12)
}

// MARK: - Connection status

enum BridgeConnectionStatus: Equatable {
    case disconnected
    case connecting
    case reconnecting
    case connected(backendOnline: Bool = true)

    static var connected: BridgeConnectionStatus { .connected(backendOnline: true) }

    var isConnected: Bool {
        if case .connected = self { return true }
        return false
    }

    var label: String {
        switch self {
        case .disconnected: return "Disconnected"
        case .connecting: return "Connecting\u{2026}"
        case .reconnecting: return "Reconnecting\u{2026}"
        case .connected(let online):
            return online ? "Connected" : "Bridge connected (backend offline)"
        }
    }

    var color: String {
        switch self {
        case .connected(true): return "green"
        case .connected(false), .reconnecting, .connecting: return "yellow"
        case .disconnected: return "red"
        }
    }
}

// MARK: - Notifications

struct BridgeNotification: Identifiable, Equatable {
    let id: String
    let title: String
    let subtitle: String?
    let body: String?
    let surfaceID: String?
    let groupID: String?  // workspace_id, project_id, etc.
}

// MARK: - Approval (for bridges that support structured approvals)

struct ApprovalRequest: Identifiable {
    let id: String
    let kind: ApprovalKind
    let summary: String
    let detail: String?
    let availableDecisions: [ApprovalDecision]
}

enum ApprovalKind: String {
    case command
    case fileChange = "file_change"
    case permission
    case userInput = "user_input"
}

enum ApprovalDecision: String {
    case accept
    case acceptForSession = "accept_for_session"
    case decline
    case cancel
}

// MARK: - Pane layout (for bridges that support it)

struct BridgePane: Identifiable {
    let id: String
    let pixelFrame: CGRect
    let containerFrame: CGSize
    let surfaceIDs: [String]
    let focusedSurfaceID: String?
    let isFocused: Bool

    var normalizedFrame: CGRect {
        guard containerFrame.width > 0, containerFrame.height > 0 else {
            return CGRect(x: 0, y: 0, width: 1, height: 1)
        }
        return CGRect(
            x: pixelFrame.origin.x / containerFrame.width,
            y: pixelFrame.origin.y / containerFrame.height,
            width: pixelFrame.size.width / containerFrame.width,
            height: pixelFrame.size.height / containerFrame.height
        )
    }
}

