import Foundation

/// Bridge implementation for cmux terminal multiplexer.
/// Wraps the existing BridgeClient WebSocket connection and translates
/// cmux-specific concepts (workspaces, surfaces, panes) into the
/// generic AgentBridge protocol.
@MainActor
final class CmuxBridge: AgentBridge {
    let provider: BridgeProvider = .cmux
    let capabilities: BridgeCapabilities = [
        .sessionManagement, .terminalIO, .outputPolling,
        .paneLayout, .surfaceSplit, .browserSurfaces
    ]

    weak var delegate: AgentBridgeDelegate?
    private(set) var connectionStatus: BridgeConnectionStatus = .disconnected

    private var client: BridgeClient?
    private var discovery: BridgeDiscovery?

    // MARK: - Lifecycle

    func connect(credentials: PairingCredentials) {
        client?.disconnect()
        let newClient = BridgeClient(credentials: credentials)
        newClient.delegate = self
        client = newClient
        connectionStatus = .connecting
        newClient.connect()
    }

    func disconnect() {
        client?.disconnect()
        client = nil
        connectionStatus = .disconnected
    }

    // MARK: - Discovery

    func startDiscovery(delegate: BridgeDiscoveryDelegate) {
        let disc = BridgeDiscovery()
        disc.delegate = delegate
        self.discovery = disc
        disc.start()
    }

    // MARK: - Groups (Workspaces)

    func listGroups(completion: @escaping ([SessionGroup]) -> Void) {
        send(method: "workspace.list", params: [:]) { result in
            if let list = result["workspaces"] as? [[String: Any]] {
                let groups = list.compactMap { dict -> SessionGroup? in
                    guard let id = dict["id"] as? String else { return nil }
                    let name = (dict["name"] as? String) ?? id
                    return SessionGroup(id: id, name: name)
                }
                completion(groups)
            } else {
                completion([])
            }
        }
    }

    func currentGroupID(completion: @escaping (String?) -> Void) {
        send(method: "workspace.current", params: [:]) { result in
            completion(result["id"] as? String)
        }
    }

    func selectGroup(_ id: String, completion: (() -> Void)?) {
        send(method: "workspace.select", params: ["workspace_id": id]) { _ in
            completion?()
        }
    }

    func createGroup(name: String?, completion: (() -> Void)?) {
        var params: [String: Any] = [:]
        if let name { params["name"] = name }
        send(method: "workspace.create", params: params) { _ in
            completion?()
        }
    }

    func closeGroup(_ id: String, completion: (() -> Void)?) {
        send(method: "workspace.close", params: ["workspace_id": id]) { _ in
            completion?()
        }
    }

    // MARK: - Surfaces

    func listSurfaces(groupID: String?, completion: @escaping ([BridgeSurface]) -> Void) {
        var params: [String: Any] = [:]
        if let id = groupID { params["workspace_id"] = id }
        send(method: "surface.list", params: params) { result in
            if let list = result["surfaces"] as? [[String: Any]] {
                let surfaces = list.compactMap { dict -> BridgeSurface? in
                    guard let id = dict["id"] as? String else { return nil }
                    let type = (dict["type"] as? String) ?? "terminal"
                    let title = (dict["title"] as? String) ?? type
                    let isFocused = dict["is_focused"] as? Bool ?? false
                    let wsID = dict["workspace_id"] as? String

                    let kind: SurfaceKind
                    switch type {
                    case "browser":
                        kind = .browser
                    default:
                        kind = .terminal
                    }

                    return BridgeSurface(
                        id: id,
                        title: title,
                        kind: kind,
                        isFocused: isFocused,
                        groupID: wsID
                    )
                }
                completion(surfaces)
            } else {
                completion([])
            }
        }
    }

    func focusSurface(_ id: String, completion: (() -> Void)?) {
        send(method: "surface.focus", params: ["surface_id": id]) { _ in
            completion?()
        }
    }

    func createSurface(type: String, completion: (() -> Void)?) {
        send(method: "surface.create", params: ["type": type]) { _ in
            completion?()
        }
    }

    func closeSurface(_ id: String, completion: (() -> Void)?) {
        send(method: "surface.close", params: ["surface_id": id]) { _ in
            completion?()
        }
    }

    // MARK: - I/O

    func sendText(_ text: String, to surfaceID: String) {
        send(method: "surface.send_text", params: ["surface_id": surfaceID, "text": text])
    }

    func sendKey(_ key: String, to surfaceID: String) {
        send(method: "surface.send_key", params: ["surface_id": surfaceID, "key": key])
    }

    // MARK: - Output reading

    func readOutput(_ surfaceID: String, lines: Int = 50, scrollback: Bool = false, groupID: String? = nil, completion: @escaping (String) -> Void) {
        var params: [String: Any] = ["surface_id": surfaceID]
        if scrollback {
            params["scrollback"] = true
        } else {
            params["lines"] = lines
        }
        if let wsID = groupID {
            params["workspace_id"] = wsID
        }
        send(method: "surface.read_text", params: params) { result in
            completion(result["text"] as? String ?? "")
        }
    }

    // MARK: - Panes

    func listPanes(groupID: String?, completion: @escaping ([BridgePane]) -> Void) {
        var params: [String: Any] = [:]
        if let id = groupID { params["workspace_id"] = id }
        send(method: "pane.list", params: params) { result in
            if let list = result["panes"] as? [[String: Any]] {
                let panes = list.compactMap { dict -> BridgePane? in
                    guard let id = dict["id"] as? String else { return nil }

                    let pixelFrame: CGRect
                    if let pf = dict["pixel_frame"] as? [String: Any] {
                        pixelFrame = CGRect(
                            x: CGFloat((pf["x"] as? Double) ?? 0),
                            y: CGFloat((pf["y"] as? Double) ?? 0),
                            width: CGFloat((pf["width"] as? Double) ?? 100),
                            height: CGFloat((pf["height"] as? Double) ?? 100)
                        )
                    } else {
                        pixelFrame = CGRect(x: 0, y: 0, width: 100, height: 100)
                    }

                    let containerFrame: CGSize
                    if let cf = dict["container_frame"] as? [String: Any] {
                        containerFrame = CGSize(
                            width: CGFloat((cf["width"] as? Double) ?? 100),
                            height: CGFloat((cf["height"] as? Double) ?? 100)
                        )
                    } else {
                        containerFrame = CGSize(width: 100, height: 100)
                    }

                    return BridgePane(
                        id: id,
                        pixelFrame: pixelFrame,
                        containerFrame: containerFrame,
                        surfaceIDs: dict["surface_ids"] as? [String] ?? [],
                        focusedSurfaceID: dict["focused_surface_id"] as? String,
                        isFocused: dict["is_focused"] as? Bool ?? false
                    )
                }
                completion(panes)
            } else {
                completion([])
            }
        }
    }

    func focusPane(_ id: String, completion: (() -> Void)?) {
        send(method: "pane.focus", params: ["pane_id": id]) { _ in
            completion?()
        }
    }

    // MARK: - Surface splitting

    func splitSurface(direction: String, surfaceID: String?, completion: (() -> Void)?) {
        var params: [String: Any] = ["direction": direction]
        if let surfaceID { params["surface_id"] = surfaceID }
        send(method: "surface.split", params: params) { _ in
            completion?()
        }
    }

    // MARK: - Browser

    func readBrowserURL(_ surfaceID: String, completion: @escaping (String) -> Void) {
        send(method: "browser.url.get", params: ["surface_id": surfaceID]) { result in
            completion(result["url"] as? String ?? "")
        }
    }

    // MARK: - Notifications

    func clearNotifications(completion: (() -> Void)?) {
        send(method: "notification.clear", params: [:]) { _ in
            completion?()
        }
    }

    // MARK: - Quick actions

    func defaultQuickActionCommands() -> [QuickActionCommand] {
        [
            QuickActionCommand(label: "claude", icon: "brain", command: "claude\n", section: "AI"),
            QuickActionCommand(label: "claude --continue", icon: "arrow.uturn.forward", command: "claude --continue\n", section: "AI"),
            QuickActionCommand(label: "claude --resume", icon: "play.circle", command: "claude --resume\n", section: "AI"),
        ]
    }

    // MARK: - Private

    private func send(
        method: String,
        params: [String: Any],
        completion: (([String: Any]) -> Void)? = nil
    ) {
        client?.send(method: method, params: params, completion: completion)
    }
}

// MARK: - BridgeClientDelegate

extension CmuxBridge: BridgeClientDelegate {
    nonisolated func clientDidConnect(_ client: BridgeClient) {
        Task { @MainActor in
            self.connectionStatus = .connected
            self.delegate?.bridgeDidConnect(self)
            self.delegate?.bridgeDidUpdateStatus(self, status: .connected)
        }
    }

    nonisolated func clientDidDisconnect(_ client: BridgeClient, error: Error?) {
        Task { @MainActor in
            self.connectionStatus = .reconnecting
            self.delegate?.bridgeDidDisconnect(self, error: error)
            self.delegate?.bridgeDidUpdateStatus(self, status: .reconnecting)
        }
    }

    nonisolated func clientDidReceiveMessage(_ client: BridgeClient, message: BridgeMessage) {
        Task { @MainActor in
            switch message {
            case .connected(let payload):
                self.connectionStatus = .connected(backendOnline: payload.cmuxConnected)
                self.delegate?.bridgeDidUpdateStatus(self, status: self.connectionStatus)

            case .notificationCreated(let n):
                let notification = BridgeNotification(
                    id: n.id,
                    title: n.title,
                    subtitle: n.subtitle,
                    body: n.body,
                    surfaceID: n.surfaceID,
                    groupID: n.workspaceID
                )
                self.delegate?.bridgeDidReceiveNotification(self, notification: notification)

            case .notificationCleared:
                self.delegate?.bridgeDidClearNotifications(self)

            case .cmuxConnected:
                self.connectionStatus = .connected(backendOnline: true)
                self.delegate?.bridgeDidUpdateStatus(self, status: self.connectionStatus)
                self.delegate?.bridgeDidConnect(self)

            case .cmuxDisconnected:
                self.connectionStatus = .connected(backendOnline: false)
                self.delegate?.bridgeDidUpdateStatus(self, status: self.connectionStatus)

            case .commandResponse:
                break // handled by BridgeClient's completion system
            }
        }
    }
}

