import SwiftUI

struct BridgePickerView: View {
    @EnvironmentObject var appState: AppState
    @Binding var selectedProvider: BridgeProvider
    @Binding var showPairing: Bool

    var body: some View {
        VStack(spacing: 24) {
            Spacer()

            Image(systemName: "antenna.radiowaves.left.and.right")
                .font(.system(size: 48, weight: .thin))
                .foregroundStyle(.tint)

            VStack(spacing: 8) {
                Text("Connect to")
                    .font(.title.bold())
                Text("Choose what you're connecting to")
                    .foregroundStyle(.secondary)
            }

            VStack(spacing: 12) {
                ForEach(BridgeProvider.allCases) { provider in
                    BridgeProviderCard(
                        provider: provider,
                        isSelected: selectedProvider == provider
                    ) {
                        selectedProvider = provider
                    }
                }
            }
            .padding(.horizontal)

            Button {
                showPairing = true
            } label: {
                Text("Continue")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)
            .padding(.horizontal)

            Spacer()
        }
    }
}

private struct BridgeProviderCard: View {
    let provider: BridgeProvider
    let isSelected: Bool
    let onTap: () -> Void

    var body: some View {
        Button(action: onTap) {
            HStack(spacing: 14) {
                Image(systemName: provider.iconName)
                    .font(.system(size: 22))
                    .frame(width: 36)
                    .foregroundStyle(isSelected ? .white : .secondary)

                VStack(alignment: .leading, spacing: 2) {
                    Text(provider.displayName)
                        .font(.headline)
                        .foregroundStyle(isSelected ? .white : .primary)
                    Text(provider.description)
                        .font(.caption)
                        .foregroundStyle(isSelected ? .white.opacity(0.7) : .secondary)
                }

                Spacer()

                if isSelected {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.system(size: 20))
                        .foregroundStyle(.white)
                }
            }
            .padding(14)
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(isSelected ? Color.accentColor : Color(.systemGray6))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 12)
                    .stroke(isSelected ? Color.accentColor : Color(.systemGray4), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }
}

