import Foundation
import Security

struct PairingCredentials: Codable {
    let host: String
    let port: Int
    let token: String
    let tailscaleHost: String?

    init(host: String, port: Int, token: String, tailscaleHost: String? = nil) {
        self.host = host
        self.port = port
        self.token = token
        self.tailscaleHost = tailscaleHost
    }
}

/// Stored pairing: credentials + which provider they belong to.
struct SavedPairing: Codable {
    let provider: BridgeProvider
    let credentials: PairingCredentials
}

final class PairingStore {
    private let service = "dev.itsmaleen.cmux-bridge"
    private let multiAccount = "multi_credentials"
    // Legacy keys for migration
    private let legacyAccount = "credentials"
    private let legacyProviderKey = "bridge_provider"

    // MARK: - Multi-bridge API

    func saveAll(_ pairings: [SavedPairing]) throws {
        let data = try JSONEncoder().encode(pairings)

        let deleteQuery: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: multiAccount,
        ]
        SecItemDelete(deleteQuery as CFDictionary)

        let addQuery: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: multiAccount,
            kSecValueData: data,
            kSecAttrAccessible: kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
        ]
        let status = SecItemAdd(addQuery as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw KeychainError.saveFailed(status)
        }
    }

    func loadAll() -> [SavedPairing] {
        // Try multi first
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: multiAccount,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitOne,
        ]
        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        if status == errSecSuccess, let data = result as? Data,
           let pairings = try? JSONDecoder().decode([SavedPairing].self, from: data) {
            return pairings
        }

        // Migrate legacy single pairing
        if let legacy = try? loadLegacy() {
            let provider = loadLegacyProvider() ?? .cmux
            let pairing = SavedPairing(provider: provider, credentials: legacy)
            try? saveAll([pairing])
            deleteLegacy()
            return [pairing]
        }

        return []
    }

    func addPairing(_ pairing: SavedPairing) throws {
        var all = loadAll()
        // Replace existing pairing for this provider
        all.removeAll { $0.provider == pairing.provider }
        all.append(pairing)
        try saveAll(all)
    }

    func removePairing(for provider: BridgeProvider) throws {
        var all = loadAll()
        all.removeAll { $0.provider == provider }
        if all.isEmpty {
            try deleteAll()
        } else {
            try saveAll(all)
        }
    }

    func deleteAll() throws {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: multiAccount,
        ]
        SecItemDelete(query as CFDictionary)
        deleteLegacy()
    }

    // MARK: - Legacy single-bridge compat

    func save(_ credentials: PairingCredentials, provider: BridgeProvider = .cmux) throws {
        try addPairing(SavedPairing(provider: provider, credentials: credentials))
    }

    func load() throws -> PairingCredentials {
        let all = loadAll()
        guard let first = all.first else { throw KeychainError.notFound }
        return first.credentials
    }

    func loadProvider() -> BridgeProvider? {
        loadAll().first?.provider
    }

    func delete() throws {
        try deleteAll()
    }

    // MARK: - Legacy keychain helpers

    private func loadLegacy() throws -> PairingCredentials {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: legacyAccount,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitOne,
        ]
        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        guard status == errSecSuccess, let data = result as? Data else {
            throw KeychainError.notFound
        }
        return try JSONDecoder().decode(PairingCredentials.self, from: data)
    }

    private func loadLegacyProvider() -> BridgeProvider? {
        guard let raw = UserDefaults.standard.string(forKey: legacyProviderKey) else { return nil }
        return BridgeProvider(rawValue: raw)
    }

    private func deleteLegacy() {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: legacyAccount,
        ]
        SecItemDelete(query as CFDictionary)
        UserDefaults.standard.removeObject(forKey: legacyProviderKey)
    }
}

enum KeychainError: Error {
    case saveFailed(OSStatus)
    case notFound
    case deleteFailed(OSStatus)
}

