import Foundation
import Combine
import UserNotifications

@MainActor
final class AppState: ObservableObject {
    @Published var connectionStatus: BridgeConnectionStatus = .disconnected
    @Published var notifications: [AgentNotification] = []
    @Published var groups: [SessionGroup] = []
    @Published var currentGroupID: String?
    @Published var surfaces: [BridgeSurface] = []
    @Published var panes: [BridgePane] = []
    @Published var isPairingPresented = false
    @Published private(set) var localFocusedSurfaceID: String?
    @Published var surfaceContent: [String: String] = [:]
    @Published var browserURLs: [String: String] = [:]

    /// All connected bridges, keyed by provider.
    @Published private(set) var bridges: [BridgeProvider: any AgentBridge] = [:]
    /// Which bridge is currently active.
    @Published private(set) var activeBridgeProvider: BridgeProvider?

    private var lastFocusedSurface: [String: String] = [:]
    let pairingStore = PairingStore()
    private var discovery: BridgeDiscovery?

    /// The currently active bridge.
    var bridge: (any AgentBridge)? {
        guard let provider = activeBridgeProvider else { return nil }
        return bridges[provider]
    }

    var bridgeCapabilities: BridgeCapabilities {
        bridge?.capabilities ?? []
    }

    /// All providers that have an active connection.
    var connectedProviders: [BridgeProvider] {
        bridges.keys.sorted { $0.rawValue < $1.rawValue }
    }

    init() {
        startDiscovery()
        connectAllPaired()
        requestNotificationPermission()
    }

    private func requestNotificationPermission() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { granted, _ in
            print("[Notification] push permission: \(granted)")
        }
    }

    private func scheduleLocalNotification(_ n: AgentNotification) {
        let center = UNUserNotificationCenter.current()
        let content = UNMutableNotificationContent()
        content.title = n.title
        if let subtitle = n.subtitle { content.subtitle = subtitle }
        if let body = n.body { content.body = body }
        content.sound = .default

        let request = UNNotificationRequest(
            identifier: n.id,
            content: content,
            trigger: nil
        )
        center.add(request)
    }

    // MARK: - Multi-bridge management

    func addBridge(provider: BridgeProvider, credentials: PairingCredentials) {
        // Disconnect existing bridge for this provider if any
        bridges[provider]?.disconnect()

        let newBridge = Self.makeBridge(for: provider)
        newBridge.delegate = self
        bridges[provider] = newBridge
        newBridge.connect(credentials: credentials)

        // Auto-activate if this is the first bridge
        if activeBridgeProvider == nil {
            switchToBridge(provider)
        }
    }

    func removeBridge(provider: BridgeProvider) {
        bridges[provider]?.disconnect()
        bridges.removeValue(forKey: provider)
        try? pairingStore.removePairing(for: provider)

        if activeBridgeProvider == provider {
            // Switch to next available bridge
            if let next = bridges.keys.first {
                switchToBridge(next)
            } else {
                activeBridgeProvider = nil
                clearActiveState()
            }
        }
    }

    func switchToBridge(_ provider: BridgeProvider) {
        guard bridges[provider] != nil else { return }
        activeBridgeProvider = provider
        connectionStatus = bridges[provider]?.connectionStatus ?? .disconnected
        clearActiveState()
        refreshGroups()
        refreshSurfaces()
        refreshPanes()
    }

    func cycleBridge() {
        let providers = connectedProviders
        guard providers.count > 1 else { return }
        let currentIndex = providers.firstIndex(of: activeBridgeProvider ?? .cmux) ?? -1
        let nextIndex = (currentIndex + 1) % providers.count
        switchToBridge(providers[nextIndex])
    }

    private func clearActiveState() {
        notifications = []
        groups = []
        surfaces = []
        panes = []
        currentGroupID = nil
        localFocusedSurfaceID = nil
        surfaceContent = [:]
        browserURLs = [:]
        lastFocusedSurface = [:]
    }

    // MARK: - Pairing

    func handlePairingURL(_ url: URL) {
        guard url.scheme == "cmux-bridge",
              url.host == "pair",
              let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              let host = components.queryItems?.first(where: { $0.name == "host" })?.value,
              let portStr = components.queryItems?.first(where: { $0.name == "port" })?.value,
              let port = Int(portStr),
              let token = components.queryItems?.first(where: { $0.name == "token" })?.value
        else { return }

        let tailscaleHost = components.queryItems?.first(where: { $0.name == "tailscale_host" })?.value
        let credentials = PairingCredentials(host: host, port: port, token: token, tailscaleHost: tailscaleHost)
        try? pairingStore.save(credentials, provider: .cmux)
        addBridge(provider: .cmux, credentials: credentials)
        isPairingPresented = false
    }

    func unpair() {
        for (_, b) in bridges { b.disconnect() }
        bridges = [:]
        activeBridgeProvider = nil
        try? pairingStore.deleteAll()
        clearActiveState()
        connectionStatus = .disconnected
    }

    func unpairProvider(_ provider: BridgeProvider) {
        removeBridge(provider: provider)
    }

    // MARK: - Connection

    func connectAllPaired() {
        let pairings = pairingStore.loadAll()
        for pairing in pairings {
            addBridge(provider: pairing.provider, credentials: pairing.credentials)
        }
    }

    func connect(to credentials: PairingCredentials, provider: BridgeProvider = .cmux) {
        try? pairingStore.save(credentials, provider: provider)
        addBridge(provider: provider, credentials: credentials)
    }

    static func makeBridge(for provider: BridgeProvider) -> any AgentBridge {
        switch provider {
        case .cmux:
            return CmuxBridge()
        case .codex:
            return CodexBridge()
        case .t3code:
            return T3CodeBridge()
        }
    }

    // MARK: - Discovery

    private func startDiscovery() {
        let disc = BridgeDiscovery()
        disc.delegate = self
        self.discovery = disc
        disc.start()
    }

    // MARK: - Group commands (workspaces, projects, etc.)

    func selectGroup(_ id: String) {
        bridge?.selectGroup(id) { [weak self] in
            self?.currentGroupID = id
            self?.localFocusedSurfaceID = self?.lastFocusedSurface[id]
            self?.refreshSurfaces()
            self?.refreshPanes()
        }
    }

    func createGroup(name: String? = nil) {
        bridge?.createGroup(name: name) { [weak self] in
            self?.refreshGroups()
            self?.refreshSurfaces()
        }
    }

    func closeGroup(_ id: String) {
        bridge?.closeGroup(id) { [weak self] in
            self?.lastFocusedSurface.removeValue(forKey: id)
            self?.refreshGroups()
            if self?.currentGroupID == id {
                if let next = self?.groups.first(where: { $0.id != id }) {
                    self?.selectGroup(next.id)
                }
            }
        }
    }

    // MARK: - Surface commands

    func focusSurface(_ id: String) {
        localFocusedSurfaceID = id
        if let gID = currentGroupID {
            lastFocusedSurface[gID] = id
        }
        bridge?.focusSurface(id) { [weak self] in
            self?.refreshSurfaces()
            self?.refreshPanes()
        }
    }

    func cycleSurface() {
        let list = surfaces
        guard !list.isEmpty else { return }
        let currentIndex = list.firstIndex(where: { $0.id == focusedSurfaceID }) ?? -1
        let nextIndex = (currentIndex + 1) % list.count
        focusSurface(list[nextIndex].id)
    }

    func cycleSurfaceBackward() {
        let list = surfaces
        guard !list.isEmpty else { return }
        let currentIndex = list.firstIndex(where: { $0.id == focusedSurfaceID }) ?? 0
        let prevIndex = (currentIndex - 1 + list.count) % list.count
        focusSurface(list[prevIndex].id)
    }

    func cycleGroup() {
        guard !groups.isEmpty else { return }
        let currentIndex = groups.firstIndex(where: { $0.id == currentGroupID }) ?? -1
        let nextIndex = (currentIndex + 1) % groups.count
        selectGroup(groups[nextIndex].id)
    }

    func cyclePane() {
        guard !panes.isEmpty else { return }
        let focusedIndex = panes.firstIndex(where: { $0.isFocused }) ?? -1
        let nextIndex = (focusedIndex + 1) % panes.count
        bridge?.focusPane(panes[nextIndex].id) { [weak self] in
            self?.refreshPanes()
        }
    }

    func cycleTabInFocusedPane() {
        guard let focused = panes.first(where: { $0.isFocused }),
              focused.surfaceIDs.count > 1 else { return }
        let currentIndex = focused.surfaceIDs.firstIndex(of: focused.focusedSurfaceID ?? "") ?? -1
        let nextIndex = (currentIndex + 1) % focused.surfaceIDs.count
        focusSurface(focused.surfaceIDs[nextIndex])
    }

    func sendText(_ text: String, to surfaceID: String) {
        bridge?.sendText(text, to: surfaceID)
    }

    func sendKey(_ key: String, to surfaceID: String) {
        bridge?.sendKey(key, to: surfaceID)
    }

    func togglePaneZoom(_ surfaceID: String) {
        sendKey("cmd+shift+enter", to: surfaceID)
    }

    func readSurfaceText(_ surfaceID: String, lines: Int = 50, scrollback: Bool = false) {
        bridge?.readOutput(surfaceID, lines: lines, scrollback: scrollback, groupID: currentGroupID) { [weak self] text in
            let trimmed = text
                .split(separator: "\n", omittingEmptySubsequences: false)
                .map { $0.replacingOccurrences(of: "\\s+$", with: "", options: .regularExpression) }
                .joined(separator: "\n")
                .replacingOccurrences(of: "\\n+$", with: "", options: .regularExpression)
            self?.surfaceContent[surfaceID] = trimmed
        }
    }

    func readBrowserURL(_ surfaceID: String) {
        bridge?.readBrowserURL(surfaceID) { [weak self] url in
            self?.browserURLs[surfaceID] = url
        }
    }

    func splitSurface(direction: String, surfaceID: String? = nil) {
        let previousIDs = Set(surfaces.map(\.id))
        bridge?.splitSurface(direction: direction, surfaceID: surfaceID) { [weak self] in
            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
        }
    }

    func createSurface(type: String = "terminal") {
        let previousIDs = Set(surfaces.map(\.id))
        bridge?.createSurface(type: type) { [weak self] in
            self?.refreshSurfacesAndFocusNew(previousIDs: previousIDs)
        }
    }

    func closeSurface(_ surfaceID: String) {
        bridge?.closeSurface(surfaceID) { [weak self] in
            self?.refreshSurfaces()
        }
    }

    func clearNotifications() {
        bridge?.clearNotifications { [weak self] in
            self?.notifications = []
        }
    }

    // MARK: - Refresh

    func refreshGroups() {
        bridge?.listGroups { [weak self] newGroups in
            self?.groups = newGroups
        }
        if let cmux = bridge as? CmuxBridge {
            cmux.currentGroupID { [weak self] id in
                self?.currentGroupID = id
            }
        }
    }

    func refreshSurfaces(groupID: String? = nil) {
        let gID = groupID ?? currentGroupID
        bridge?.listSurfaces(groupID: gID) { [weak self] newSurfaces in
            self?.surfaces = newSurfaces
            if let localID = self?.localFocusedSurfaceID,
               !newSurfaces.contains(where: { $0.id == localID }) {
                self?.localFocusedSurfaceID = nil
            }
            if self?.focusedSurfaceID == nil, let first = newSurfaces.first {
                self?.localFocusedSurfaceID = first.id
            }
        }
    }

    private func refreshSurfacesAndFocusNew(previousIDs: Set<String>) {
        bridge?.listSurfaces(groupID: currentGroupID) { [weak self] newSurfaces in
            guard let self else { return }
            self.surfaces = newSurfaces
            if let newSurface = newSurfaces.first(where: { !previousIDs.contains($0.id) }) {
                self.focusSurface(newSurface.id)
            } else if self.focusedSurfaceID == nil, let first = newSurfaces.first {
                self.localFocusedSurfaceID = first.id
            }
        }
    }

    func refreshPanes() {
        guard bridgeCapabilities.contains(.paneLayout) else { return }
        bridge?.listPanes(groupID: currentGroupID) { [weak self] newPanes in
            self?.panes = newPanes
        }
    }

    // MARK: - Helpers

    var focusedSurfaceID: String? {
        panes.first(where: { $0.isFocused })?.focusedSurfaceID
            ?? surfaces.first(where: { $0.isFocused })?.id
            ?? localFocusedSurfaceID
    }

    var currentGroupSurfaces: [BridgeSurface] {
        guard let gID = currentGroupID else { return surfaces }
        return surfaces.filter { $0.groupID == gID }
    }

    func surfaceTitle(for id: String) -> String {
        surfaces.first(where: { $0.id == id })?.title ?? ""
    }

    func hasNotification(for pane: BridgePane) -> Bool {
        notifications.contains { n in
            guard let sid = n.surfaceID else { return false }
            return pane.surfaceIDs.contains(sid)
        }
    }

    func hasNotification(for surface: BridgeSurface) -> Bool {
        notifications.contains { $0.surfaceID == surface.id }
    }

    func clearNotificationsForFocusedSurface() {
        guard let focusedID = focusedSurfaceID else { return }
        notifications.removeAll { $0.surfaceID == focusedID }
    }

    var groupLabel: String {
        switch activeBridgeProvider {
        case .cmux: return "Workspace"
        case .codex: return "Thread"
        case .t3code: return "Project"
        case nil: return "Session"
        }
    }

    var groupLabelPlural: String {
        switch activeBridgeProvider {
        case .cmux: return "Workspaces"
        case .codex: return "Threads"
        case .t3code: return "Projects"
        case nil: return "Sessions"
        }
    }
}

// MARK: - AgentBridgeDelegate

extension AppState: AgentBridgeDelegate {
    func bridgeDidConnect(_ bridge: any AgentBridge) {
        // Only refresh if this is the active bridge
        guard bridge.provider == activeBridgeProvider else { return }
        refreshGroups()
        refreshSurfaces()
        refreshPanes()
    }

    func bridgeDidDisconnect(_ bridge: any AgentBridge, error: Error?) {
        guard bridge.provider == activeBridgeProvider else { return }
        connectionStatus = .reconnecting
    }

    func bridgeDidUpdateStatus(_ bridge: any AgentBridge, status: BridgeConnectionStatus) {
        guard bridge.provider == activeBridgeProvider else { return }
        connectionStatus = status
    }

    func bridgeDidUpdateSurfaces(_ bridge: any AgentBridge, surfaces: [BridgeSurface]) {
        guard bridge.provider == activeBridgeProvider else { return }
        self.surfaces = surfaces
    }

    func bridgeDidUpdateGroups(_ bridge: any AgentBridge, groups: [SessionGroup]) {
        guard bridge.provider == activeBridgeProvider else { return }
        self.groups = groups
    }

    func bridgeDidUpdatePanes(_ bridge: any AgentBridge, panes: [BridgePane]) {
        guard bridge.provider == activeBridgeProvider else { return }
        self.panes = panes
    }

    func bridgeDidReceiveNotification(_ bridge: any AgentBridge, notification: AgentNotification) {
        // Show notifications from any bridge
        notifications.insert(notification, at: 0)
        scheduleLocalNotification(notification)
    }

    func bridgeDidClearNotifications(_ bridge: any AgentBridge) {
        guard bridge.provider == activeBridgeProvider else { return }
        notifications = []
    }

    func bridgeDidReceiveApproval(_ bridge: any AgentBridge, request: ApprovalRequest) {
        // TODO: Show approval UI for bridges that support structured approvals
    }
}

// MARK: - BridgeDiscoveryDelegate

extension AppState: BridgeDiscoveryDelegate {
    func discovery(_ discovery: BridgeDiscovery, didFind candidates: [PairingCredentials]) {
        // Only auto-connect cmux via discovery
        let pairings = pairingStore.loadAll()
        guard let cmuxPairing = pairings.first(where: { $0.provider == .cmux }),
              bridges[.cmux] == nil || !(bridges[.cmux]?.connectionStatus.isConnected ?? false)
        else { return }

        if let match = candidates.first(where: { $0.host == cmuxPairing.credentials.host && $0.port == cmuxPairing.credentials.port }) {
            let creds = PairingCredentials(host: match.host, port: match.port, token: cmuxPairing.credentials.token, tailscaleHost: cmuxPairing.credentials.tailscaleHost)
            addBridge(provider: .cmux, credentials: creds)
        }
    }
}

