import SwiftUI

struct SettingsView: View {
    @EnvironmentObject var appState: AppState
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @State private var showUnpairConfirm = false
    @State private var providerToUnpair: BridgeProvider?

    var body: some View {
        NavigationStack {
            Form {
                Section("Active Bridge") {
                    if let provider = appState.activeBridgeProvider {
                        HStack {
                            Image(systemName: provider.iconName)
                                .foregroundStyle(.tint)
                            Text(provider.displayName)
                                .font(.headline)
                            Spacer()
                            Text(appState.connectionStatus.label)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }

                        if !appState.bridgeCapabilities.isEmpty {
                            LabeledContent("Capabilities") {
                                Text(capabilityLabels.joined(separator: ", "))
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                        }
                    } else {
                        Text("No bridge connected")
                            .foregroundStyle(.secondary)
                    }

                    if appState.connectedProviders.count > 1 {
                        Button {
                            appState.cycleBridge()
                        } label: {
                            Label("Switch Bridge", systemImage: "arrow.triangle.2.circlepath")
                        }
                    }
                }

                if !appState.connectedProviders.isEmpty {
                    Section("Connected Bridges") {
                        ForEach(appState.connectedProviders, id: \.self) { provider in
                            let isActive = provider == appState.activeBridgeProvider
                            let bridge = appState.bridges[provider]
                            HStack {
                                Image(systemName: provider.iconName)
                                    .foregroundStyle(isActive ? .tint : .secondary)
                                    .frame(width: 24)
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(provider.displayName)
                                        .font(.system(size: 14, weight: isActive ? .semibold : .regular))
                                    Text(bridge?.connectionStatus.label ?? "Unknown")
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                }
                                Spacer()
                                if isActive {
                                    Image(systemName: "checkmark.circle.fill")
                                        .foregroundStyle(.tint)
                                }
                            }
                            .contentShape(Rectangle())
                            .onTapGesture {
                                appState.switchToBridge(provider)
                            }
                            .swipeActions(edge: .trailing) {
                                Button(role: .destructive) {
                                    providerToUnpair = provider
                                    showUnpairConfirm = true
                                } label: {
                                    Label("Remove", systemImage: "trash")
                                }
                            }
                        }
                    }
                }

                Section("Quick Actions") {
                    NavigationLink("Manage Quick Actions") {
                        QuickActionSettingsView()
                    }
                }

                Section("Speech Input") {
                    Toggle("Auto-submit speech", isOn: $autoSubmitSpeech)
                    Text("When enabled, automatically presses Enter after sending speech text.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }

                Section {
                    Button("Add Bridge") {
                        appState.isPairingPresented = true
                    }

                    if !appState.bridges.isEmpty {
                        Button("Remove All", role: .destructive) {
                            appState.unpair()
                        }
                    }
                }
            }
            .navigationTitle("Settings")
            .confirmationDialog(
                "Remove \(providerToUnpair?.displayName ?? "bridge")?",
                isPresented: $showUnpairConfirm,
                titleVisibility: .visible
            ) {
                Button("Remove", role: .destructive) {
                    if let provider = providerToUnpair {
                        appState.unpairProvider(provider)
                    }
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("You will need to set up this bridge again to reconnect.")
            }
        }
    }

    private var capabilityLabels: [String] {
        let caps = appState.bridgeCapabilities
        var labels: [String] = []
        if caps.contains(.terminalIO) { labels.append("Terminal I/O") }
        if caps.contains(.outputPolling) { labels.append("Polling") }
        if caps.contains(.outputStreaming) { labels.append("Streaming") }
        if caps.contains(.paneLayout) { labels.append("Panes") }
        if caps.contains(.surfaceSplit) { labels.append("Split") }
        if caps.contains(.browserSurfaces) { labels.append("Browser") }
        if caps.contains(.structuredApprovals) { labels.append("Approvals") }
        if caps.contains(.agentStatus) { labels.append("Agent Status") }
        if caps.contains(.fileDiffs) { labels.append("Diffs") }
        if caps.contains(.gitOperations) { labels.append("Git") }
        if caps.contains(.multiAgent) { labels.append("Multi-Agent") }
        return labels
    }
}

