import SwiftUI

struct PairingView: View {
    @EnvironmentObject var appState: AppState
    @State private var selectedProvider: BridgeProvider = .cmux
    @State private var showPairingFlow = false
    @State private var showScanner = false
    @State private var showManual = false

    var body: some View {
        NavigationStack {
            if !showPairingFlow {
                BridgePickerView(
                    selectedProvider: $selectedProvider,
                    showPairing: $showPairingFlow
                )
                .navigationTitle("Setup")
                .navigationBarTitleDisplayMode(.inline)
            } else {
                pairingFlow
                    .navigationTitle("Pair with \(selectedProvider.displayName)")
                    .navigationBarTitleDisplayMode(.inline)
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Back") {
                                showPairingFlow = false
                            }
                        }
                    }
            }
        }
    }

    private var pairingFlow: some View {
        VStack(spacing: 24) {
            Spacer()

            Image(systemName: selectedProvider.iconName)
                .font(.system(size: 64))
                .foregroundStyle(.tint)

            VStack(spacing: 8) {
                Text("Pair with \(selectedProvider.displayName)")
                    .font(.title2.bold())
                Text(pairingInstructions)
                    .multilineTextAlignment(.center)
                    .foregroundStyle(.secondary)
                    .padding(.horizontal)
            }

            if selectedProvider == .cmux {
                Button {
                    showScanner = true
                } label: {
                    Label("Scan QR Code", systemImage: "qrcode.viewfinder")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
                .padding(.horizontal)
            }

            Button("Enter manually") {
                showManual = true
            }
            .foregroundStyle(.secondary)

            Spacer()
        }
        .sheet(isPresented: $showScanner) {
            QRScannerView { scannedURL in
                showScanner = false
                if let url = URL(string: scannedURL) {
                    appState.handlePairingURL(url)
                }
            }
        }
        .sheet(isPresented: $showManual) {
            ManualPairingView(provider: selectedProvider)
        }
    }

    private var pairingInstructions: String {
        switch selectedProvider {
        case .cmux:
            return "Scan the QR code shown by\n`cmux-bridge --pair` on your Mac."
        case .codex:
            return "Run `codex app-server --listen ws://0.0.0.0:PORT` on your machine, then enter the connection details."
        case .t3code:
            return "Make sure T3 Code is running on your machine. It listens on port 3773 by default."
        }
    }
}

private struct ManualPairingView: View {
    let provider: BridgeProvider
    @EnvironmentObject var appState: AppState
    @Environment(\.dismiss) private var dismiss
    @State private var host = ""
    @State private var port: String
    @State private var token = ""

    init(provider: BridgeProvider) {
        self.provider = provider
        _port = State(initialValue: String(provider.defaultPort))
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Connection") {
                    TextField("Host or IP", text: $host)
                        .keyboardType(.URL)
                        .autocorrectionDisabled()
                        .textInputAutocapitalization(.never)
                    TextField("Port", text: $port)
                        .keyboardType(.numberPad)
                }

                if provider == .cmux || provider == .codex {
                    Section("Authentication") {
                        TextField(tokenPlaceholder, text: $token)
                            .autocorrectionDisabled()
                            .textInputAutocapitalization(.never)
                    }
                }

                Section {
                    Text(connectionHint)
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
            }
            .navigationTitle("Manual pairing")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Connect") {
                        guard let portInt = Int(port), !host.isEmpty else { return }
                        // Token is optional for t3code
                        if provider != .t3code && token.isEmpty { return }
                        let creds = PairingCredentials(host: host, port: portInt, token: token)
                        try? PairingStore().save(creds, provider: provider)
                        appState.connect(to: creds, provider: provider)
                        dismiss()
                    }
                    .disabled(host.isEmpty || (provider != .t3code && token.isEmpty))
                }
            }
        }
    }

    private var tokenPlaceholder: String {
        switch provider {
        case .cmux: return "Paste token from cmux-bridge --pair"
        case .codex: return "Bearer token (if configured)"
        case .t3code: return ""
        }
    }

    private var connectionHint: String {
        switch provider {
        case .cmux:
            return "Run `cmux-bridge --pair` on your Mac to get the connection details."
        case .codex:
            return "Run `codex app-server --listen ws://0.0.0.0:PORT` to start the WebSocket server."
        case .t3code:
            return "T3 Code runs on localhost:3773 by default. Enter your machine's IP if connecting over the network."
        }
    }
}

