// MARK: - Pairing

/// Handle a pairing URL from QR scan or deep link.
/// Supports schemes: cmux-bridge://, codex-bridge://, t3code-bridge://
/// All use the same format: scheme://pair?host=...&port=...&token=...
/// providerHint is used when the QR contains a generic scheme (e.g. just a ws:// URL).
func handlePairingURL(_ url: URL, providerHint: BridgeProvider? = nil) {
    // Determine provider from URL scheme or hint
    let provider: BridgeProvider
    switch url.scheme {
    case "cmux-bridge": provider = .cmux
    case "codex-bridge": provider = .codex
    case "t3code-bridge": provider = .t3code
    default:
        // Try parsing as a ws:// URL (e.g. ws://192.168.1.5:4080)
        if let hint = providerHint, (url.scheme == "ws" || url.scheme == "wss"),
           let host = url.host, let port = url.port {
            let creds = PairingCredentials(host: host, port: port, token: "")
            try? pairingStore.save(creds, provider: hint)
            addBridge(provider: hint, credentials: creds)
            isPairingPresented = false
            return
        }
        // Fall back to hint if scheme is unrecognized
        guard let hint = providerHint else { return }
        provider = hint
    }

    guard url.host == "pair",
          let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
          let host = components.queryItems?.first(where: { $0.name == "host" })?.value,
          let portStr = components.queryItems?.first(where: { $0.name == "port" })?.value,
          let port = Int(portStr)
    else { return }

    let token = components.queryItems?.first(where: { $0.name == "token" })?.value ?? ""
    let tailscaleHost = components.queryItems?.first(where: { $0.name == "tailscale_host" })?.value
    let credentials = PairingCredentials(host: host, port: port, token: token, tailscaleHost: tailscaleHost)
    try? pairingStore.save(credentials, provider: provider)
    addBridge(provider: provider, credentials: credentials)
    isPairingPresented = false
}

