import Foundation

/// Bridge implementation for OpenAI Codex CLI.
/// Connects to `codex app-server --listen ws://host:port` via WebSocket.
/// Supports structured approvals, streaming output, thread management,
/// and full PTY terminal access.
@MainActor
final class CodexBridge: AgentBridge {
    let provider: BridgeProvider = .codex
    let capabilities: BridgeCapabilities = [
        .sessionManagement, .terminalIO, .outputStreaming,
        .structuredApprovals, .agentStatus, .fileDiffs, .terminalResize
    ]

    weak var delegate: AgentBridgeDelegate?
    private(set) var connectionStatus: BridgeConnectionStatus = .disconnected

    private var task: URLSessionWebSocketTask?
    private var session: URLSession?
    private var wsDelegate: CodexWSDelegate?
    private var shouldReconnect = true
    private var backoff: TimeInterval = 1
    private var credentials: PairingCredentials?
    private var completions: [String: ([String: Any]) -> Void] = [:]
    private var nextID = 1

    // MARK: - Lifecycle

    func connect(credentials: PairingCredentials) {
        self.credentials = credentials
        shouldReconnect = true
        startConnection()
    }

    func disconnect() {
        shouldReconnect = false
        task?.cancel(with: .normalClosure, reason: nil)
        task = nil
        connectionStatus = .disconnected
    }

    // MARK: - Groups (Threads)

    func listGroups(completion: @escaping ([SessionGroup]) -> Void) {
        send(method: "thread/list", params: [:]) { result in
            if let threads = result["threads"] as? [[String: Any]] {
                let groups = threads.compactMap { dict -> SessionGroup? in
                    guard let id = dict["id"] as? String else { return nil }
                    let title = (dict["title"] as? String) ?? (dict["agentNickname"] as? String) ?? id
                    return SessionGroup(id: id, name: title)
                }
                completion(groups)
            } else {
                completion([])
            }
        }
    }

    func selectGroup(_ id: String, completion: (() -> Void)?) {
        // Codex doesn't have a "select" concept — threads are independent
        completion?()
    }

    func createGroup(name: String?, completion: (() -> Void)?) {
        // Thread creation happens via thread/start with a turn
        completion?()
    }

    func closeGroup(_ id: String, completion: (() -> Void)?) {
        send(method: "thread/close", params: ["threadId": id]) { _ in
            completion?()
        }
    }

    // MARK: - Surfaces (Terminals / Agent sessions)

    func listSurfaces(groupID: String?, completion: @escaping ([BridgeSurface]) -> Void) {
        // List loaded threads as agent surfaces
        send(method: "thread/loaded/list", params: [:]) { result in
            if let threads = result["threads"] as? [[String: Any]] {
                let surfaces = threads.compactMap { dict -> BridgeSurface? in
                    guard let id = dict["id"] as? String else { return nil }
                    let title = (dict["title"] as? String) ?? "codex"
                    let status = dict["status"] as? String ?? "idle"

                    let agentStatus: AgentStatus
                    switch status {
                    case "active": agentStatus = .working
                    case "idle": agentStatus = .idle
                    default: agentStatus = .unknown
                    }

                    return BridgeSurface(
                        id: id,
                        title: title,
                        kind: .agent(AgentInfo(agent: "codex", agentStatus: agentStatus)),
                        isFocused: false,
                        groupID: nil
                    )
                }
                completion(surfaces)
            } else {
                completion([])
            }
        }
    }

    func focusSurface(_ id: String, completion: (() -> Void)?) {
        completion?()
    }

    func createSurface(type: String, completion: (() -> Void)?) {
        completion?()
    }

    func closeSurface(_ id: String, completion: (() -> Void)?) {
        send(method: "thread/close", params: ["threadId": id]) { _ in
            completion?()
        }
    }

    // MARK: - I/O

    func sendText(_ text: String, to surfaceID: String) {
        // Send as a new turn to the thread
        let params: [String: Any] = [
            "threadId": surfaceID,
            "turnInput": ["text": text]
        ]
        send(method: "thread/turn/start", params: params)
    }

    func sendKey(_ key: String, to surfaceID: String) {
        // Map key to terminal control sequence for active command/exec
        // Keys like ctrl+c map to interrupt
        if key == "ctrl+c" {
            send(method: "thread/turn/interrupt", params: ["threadId": surfaceID])
        }
    }

    // MARK: - Output reading

    func readOutput(_ surfaceID: String, lines: Int = 50, scrollback: Bool = false, groupID: String? = nil, completion: @escaping (String) -> Void) {
        // Read thread messages as text output
        send(method: "thread/read", params: ["threadId": surfaceID]) { result in
            if let messages = result["messages"] as? [[String: Any]] {
                let text = messages.compactMap { msg -> String? in
                    let role = msg["role"] as? String ?? ""
                    let content = msg["text"] as? String ?? ""
                    guard !content.isEmpty else { return nil }
                    return role == "assistant" ? content : "> \(content)"
                }.joined(separator: "\n\n")
                completion(text)
            } else {
                completion("")
            }
        }
    }

    // MARK: - Notifications

    func clearNotifications(completion: (() -> Void)?) {
        completion?()
    }

    // MARK: - Approvals

    func respondToApproval(_ requestID: String, decision: ApprovalDecision, completion: (() -> Void)?) {
        let params: [String: Any] = [
            "id": requestID,
            "decision": decision.rawValue
        ]
        send(method: "serverRequest/respond", params: params) { _ in
            completion?()
        }
    }

    // MARK: - Quick actions

    func defaultQuickActionCommands() -> [QuickActionCommand] {
        [
            QuickActionCommand(label: "New thread", icon: "plus.message", command: "", section: "AI"),
            QuickActionCommand(label: "Interrupt", icon: "stop.circle", command: "", section: "AI"),
        ]
    }

    // MARK: - Private

    private func startConnection() {
        guard let credentials else {
            print("[CodexBridge] no credentials")
            return
        }
        connectionStatus = .connecting
        delegate?.bridgeDidUpdateStatus(self, status: .connecting)

        let urlString = "ws://\(credentials.host):\(credentials.port)"
        print("[CodexBridge] connecting to \(urlString)")
        guard let url = URL(string: urlString) else {
            print("[CodexBridge] invalid URL")
            return
        }

        var request = URLRequest(url: url)
        if !credentials.token.isEmpty {
            request.setValue("Bearer \(credentials.token)", forHTTPHeaderField: "Authorization")
        }
        request.timeoutInterval = 10

        let wsDelegate = CodexWSDelegate(bridge: self)
        self.wsDelegate = wsDelegate
        let session = URLSession(configuration: .default, delegate: wsDelegate, delegateQueue: nil)
        self.session = session
        let task = session.webSocketTask(with: request)
        self.task = task
        task.resume()
        receiveNext()
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            switch result {
            case .success(let message):
                Task { @MainActor in
                    self.handleMessage(message)
                }
                self.receiveNext()
            case .failure:
                Task { @MainActor in
                    self.handleDisconnect()
                }
            }
        }
    }

    private func handleMessage(_ message: URLSessionWebSocketTask.Message) {
        guard case .string(let text) = message,
              let data = text.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return }

        // Handle command response
        if let id = json["id"] as? String ?? (json["id"] as? Int).map({ String($0) }),
           let completion = completions.removeValue(forKey: id) {
            let result = json["result"] as? [String: Any] ?? json
            completion(result)
            return
        }

        // Handle server-initiated requests (approvals)
        let method = json["method"] as? String ?? ""
        let params = json["params"] as? [String: Any] ?? [:]

        switch method {
        case "item/commandExecution/requestApproval",
             "item/fileChange/requestApproval",
             "item/permissions/requestApproval":
            let requestID = json["id"] as? String ?? UUID().uuidString
            let command = params["command"] as? String
            let summary = command ?? (params["description"] as? String) ?? "Approval requested"

            let kind: ApprovalKind
            if method.contains("commandExecution") { kind = .command }
            else if method.contains("fileChange") { kind = .fileChange }
            else { kind = .permission }

            let request = ApprovalRequest(
                id: requestID,
                kind: kind,
                summary: summary,
                detail: params["changes"] as? String,
                availableDecisions: [.accept, .acceptForSession, .decline]
            )
            delegate?.bridgeDidReceiveApproval(self, request: request)

            // Also surface as a notification
            let notification = AgentNotification(
                id: requestID,
                title: "Approval needed",
                subtitle: kind.rawValue,
                body: summary,
                surfaceID: params["threadId"] as? String,
                groupID: nil
            )
            delegate?.bridgeDidReceiveNotification(self, notification: notification)

        case "thread/status/changed":
            // Refresh surfaces on status change
            delegate?.bridgeDidConnect(self)

        default:
            break
        }
    }

    func handleConnected() {
        backoff = 1
        connectionStatus = .connected
        delegate?.bridgeDidUpdateStatus(self, status: .connected)

        // Send initialize handshake
        send(method: "initialize", params: [
            "clientName": "cmux-companion",
            "clientVersion": "1.0"
        ]) { [weak self] _ in
            guard let self else { return }
            self.delegate?.bridgeDidConnect(self)
        }
    }

    func handleDisconnect() {
        task = nil
        connectionStatus = .reconnecting
        delegate?.bridgeDidUpdateStatus(self, status: .reconnecting)
        delegate?.bridgeDidDisconnect(self, error: nil)
        guard shouldReconnect else { return }
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        let delay = backoff
        backoff = min(backoff * 2, 30)
        Task {
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard self.shouldReconnect else { return }
            self.startConnection()
        }
    }

    private func send(
        method: String,
        params: [String: Any],
        completion: (([String: Any]) -> Void)? = nil
    ) {
        let id = String(nextID)
        nextID += 1
        var payload: [String: Any] = ["method": method, "params": params, "id": id]
        // Codex uses JSON-RPC 2.0 but omits jsonrpc on wire

        if let completion {
            completions[id] = completion
        }

        guard let data = try? JSONSerialization.data(withJSONObject: payload),
              let task else { return }

        task.send(.string(String(data: data, encoding: .utf8)!)) { _ in }
    }
}

// MARK: - WebSocket delegate

private final class CodexWSDelegate: NSObject, URLSessionWebSocketDelegate {
    weak var bridge: CodexBridge?

    init(bridge: CodexBridge) {
        self.bridge = bridge
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didOpenWithProtocol proto: String?) {
        Task { @MainActor in
            self.bridge?.handleConnected()
        }
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didCloseWith closeCode: URLSessionWebSocketTask.CloseCode, reason: Data?) {
        Task { @MainActor in
            self.bridge?.handleDisconnect()
        }
    }
}

