import Foundation
import CoreGraphics

// MARK: - Bridge Provider

enum BridgeProvider: String, Codable, CaseIterable, Identifiable {
    case cmux
    case codex
    case t3code

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .cmux: return "cmux"
        case .codex: return "Codex"
        case .t3code: return "T3 Code"
        }
    }

    var description: String {
        switch self {
        case .cmux: return "Terminal multiplexer for AI coding agents"
        case .codex: return "OpenAI Codex CLI"
        case .t3code: return "T3 Code desktop app"
        }
    }

    var iconName: String {
        switch self {
        case .cmux: return "rectangle.split.3x1"
        case .codex: return "chevron.left.forwardslash.chevron.right"
        case .t3code: return "square.stack.3d.up"
        }
    }

    var defaultPort: Int {
        switch self {
        case .cmux: return 47821
        case .codex: return 0 // user-specified
        case .t3code: return 3773
        }
    }
}

// MARK: - Surface model

enum SurfaceKind: Equatable {
    case agent(AgentInfo)
    case terminal
    case browser
}

struct AgentInfo: Equatable {
    let agent: String  // "claude", "opencode", "aider", "codex"
    let agentStatus: AgentStatus
}

enum AgentStatus: String, Equatable {
    case idle
    case working
    case waitingApproval = "waiting_approval"
    case error
    case unknown
}

struct BridgeSurface: Identifiable {
    let id: String
    let title: String
    let kind: SurfaceKind
    let isFocused: Bool
    let groupID: String?  // workspace ID, project ID, etc.

    var isAgent: Bool {
        if case .agent = kind { return true }
        return false
    }

    var isBrowser: Bool { kind == .browser }
    var isTerminal: Bool { kind == .terminal }
}

// MARK: - Session group (workspace, project, etc.)

struct SessionGroup: Identifiable {
    let id: String
    let name: String
}

// MARK: - Capabilities

struct BridgeCapabilities: OptionSet {
    let rawValue: Int

    static let sessionManagement    = BridgeCapabilities(rawValue: 1 << 0)
    static let terminalIO           = BridgeCapabilities(rawValue: 1 << 1)
    static let outputStreaming       = BridgeCapabilities(rawValue: 1 << 2)
    static let outputPolling         = BridgeCapabilities(rawValue: 1 << 3)
    static let structuredApprovals   = BridgeCapabilities(rawValue: 1 << 4)
    static let agentStatus           = BridgeCapabilities(rawValue: 1 << 5)
    static let fileDiffs             = BridgeCapabilities(rawValue: 1 << 6)
    static let gitOperations         = BridgeCapabilities(rawValue: 1 << 7)
    static let multiAgent            = BridgeCapabilities(rawValue: 1 << 8)
    static let terminalResize        = BridgeCapabilities(rawValue: 1 << 9)
    static let paneLayout            = BridgeCapabilities(rawValue: 1 << 10)
    static let surfaceSplit          = BridgeCapabilities(rawValue: 1 << 11)
    static let browserSurfaces       = BridgeCapabilities(rawValue: 1 << 12)
}

// MARK: - Connection status

enum BridgeConnectionStatus: Equatable {
    case disconnected
    case connecting
    case reconnecting
    case connected(backendOnline: Bool = true)

    static var connected: BridgeConnectionStatus { .connected(backendOnline: true) }

    var isConnected: Bool {
        if case .connected = self { return true }
        return false
    }

    var label: String {
        switch self {
        case .disconnected: return "Disconnected"
        case .connecting: return "Connecting\u{2026}"
        case .reconnecting: return "Reconnecting\u{2026}"
        case .connected(let online):
            return online ? "Connected" : "Bridge connected (backend offline)"
        }
    }

    var color: String {
        switch self {
        case .connected(true): return "green"
        case .connected(false), .reconnecting, .connecting: return "yellow"
        case .disconnected: return "red"
        }
    }
}

// MARK: - Notifications

struct AgentNotification: Identifiable, Equatable {
    let id: String
    let title: String
    let subtitle: String?
    let body: String?
    let surfaceID: String?
    let groupID: String?  // workspace_id, project_id, etc.
}

// MARK: - Approval (for bridges that support structured approvals)

struct ApprovalRequest: Identifiable {
    let id: String
    let kind: ApprovalKind
    let summary: String
    let detail: String?
    let availableDecisions: [ApprovalDecision]
}

enum ApprovalKind: String {
    case command
    case fileChange = "file_change"
    case permission
    case userInput = "user_input"
}

enum ApprovalDecision: String {
    case accept
    case acceptForSession = "accept_for_session"
    case decline
    case cancel
}

// MARK: - Pane layout (for bridges that support it)

struct BridgePane: Identifiable {
    let id: String
    let pixelFrame: CGRect
    let containerFrame: CGSize
    let surfaceIDs: [String]
    let focusedSurfaceID: String?
    let isFocused: Bool

    var normalizedFrame: CGRect {
        guard containerFrame.width > 0, containerFrame.height > 0 else {
            return CGRect(x: 0, y: 0, width: 1, height: 1)
        }
        return CGRect(
            x: pixelFrame.origin.x / containerFrame.width,
            y: pixelFrame.origin.y / containerFrame.height,
            width: pixelFrame.size.width / containerFrame.width,
            height: pixelFrame.size.height / containerFrame.height
        )
    }
}

// MARK: - Bridge delegate

@MainActor
protocol AgentBridgeDelegate: AnyObject {
    func bridgeDidConnect(_ bridge: any AgentBridge)
    func bridgeDidDisconnect(_ bridge: any AgentBridge, error: Error?)
    func bridgeDidUpdateStatus(_ bridge: any AgentBridge, status: BridgeConnectionStatus)
    func bridgeDidUpdateSurfaces(_ bridge: any AgentBridge, surfaces: [BridgeSurface])
    func bridgeDidUpdateGroups(_ bridge: any AgentBridge, groups: [SessionGroup])
    func bridgeDidUpdatePanes(_ bridge: any AgentBridge, panes: [BridgePane])
    func bridgeDidReceiveNotification(_ bridge: any AgentBridge, notification: AgentNotification)
    func bridgeDidClearNotifications(_ bridge: any AgentBridge)
    func bridgeDidReceiveApproval(_ bridge: any AgentBridge, request: ApprovalRequest)
}

// Default no-op implementations
extension AgentBridgeDelegate {
    func bridgeDidUpdatePanes(_ bridge: any AgentBridge, panes: [BridgePane]) {}
    func bridgeDidReceiveApproval(_ bridge: any AgentBridge, request: ApprovalRequest) {}
}

// MARK: - Bridge protocol

@MainActor
protocol AgentBridge: AnyObject {
    var provider: BridgeProvider { get }
    var capabilities: BridgeCapabilities { get }
    var connectionStatus: BridgeConnectionStatus { get }
    var delegate: AgentBridgeDelegate? { get set }

    // Lifecycle
    func connect(credentials: PairingCredentials)
    func disconnect()

    // Groups (workspaces, projects, etc.)
    func listGroups(completion: @escaping ([SessionGroup]) -> Void)
    func selectGroup(_ id: String, completion: (() -> Void)?)
    func createGroup(name: String?, completion: (() -> Void)?)
    func closeGroup(_ id: String, completion: (() -> Void)?)

    // Surfaces
    func listSurfaces(groupID: String?, completion: @escaping ([BridgeSurface]) -> Void)
    func focusSurface(_ id: String, completion: (() -> Void)?)
    func createSurface(type: String, completion: (() -> Void)?)
    func closeSurface(_ id: String, completion: (() -> Void)?)

    // I/O
    func sendText(_ text: String, to surfaceID: String)
    func sendKey(_ key: String, to surfaceID: String)

    // Output reading (polling bridges)
    func readOutput(_ surfaceID: String, lines: Int, scrollback: Bool, groupID: String?, completion: @escaping (String) -> Void)

    // Pane layout (optional)
    func listPanes(groupID: String?, completion: @escaping ([BridgePane]) -> Void)
    func focusPane(_ id: String, completion: (() -> Void)?)

    // Surface splitting (optional)
    func splitSurface(direction: String, surfaceID: String?, completion: (() -> Void)?)

    // Browser (optional)
    func readBrowserURL(_ surfaceID: String, completion: @escaping (String) -> Void)

    // Notifications
    func clearNotifications(completion: (() -> Void)?)

    // Approvals (optional)
    func respondToApproval(_ requestID: String, decision: ApprovalDecision, completion: (() -> Void)?)

    // Provider-specific quick actions
    func defaultQuickActionCommands() -> [QuickActionCommand]
}

// Default implementations for optional capabilities
extension AgentBridge {
    func listPanes(groupID: String?, completion: @escaping ([BridgePane]) -> Void) { completion([]) }
    func focusPane(_ id: String, completion: (() -> Void)?) { completion?() }
    func splitSurface(direction: String, surfaceID: String?, completion: (() -> Void)?) { completion?() }
    func readBrowserURL(_ surfaceID: String, completion: @escaping (String) -> Void) { completion("") }
    func respondToApproval(_ requestID: String, decision: ApprovalDecision, completion: (() -> Void)?) { completion?() }
}

// Quick action template per provider
struct QuickActionCommand {
    let label: String
    let icon: String
    let command: String
    let section: String
}

import SwiftUI

struct SettingsView: View {
    @EnvironmentObject var appState: AppState
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @State private var showUnpairConfirm = false
    @State private var providerToUnpair: BridgeProvider?
    @State private var expandedSetupGuide: BridgeProvider?

    var body: some View {
        NavigationStack {
            Form {
                Section("Active Bridge") {
                    if let provider = appState.activeBridgeProvider {
                        HStack {
                            Image(systemName: provider.iconName)
                                .foregroundStyle(.tint)
                            Text(provider.displayName)
                                .font(.headline)
                            Spacer()
                            Text(appState.connectionStatus.label)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }

                        if !appState.bridgeCapabilities.isEmpty {
                            LabeledContent("Capabilities") {
                                Text(capabilityLabels.joined(separator: ", "))
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                        }
                    } else {
                        Text("No bridge connected")
                            .foregroundStyle(.secondary)
                    }

                    if appState.connectedProviders.count > 1 {
                        Button {
                            appState.cycleBridge()
                        } label: {
                            Label("Switch Bridge", systemImage: "arrow.triangle.2.circlepath")
                        }
                    }
                }

                if !appState.connectedProviders.isEmpty {
                    Section("Connected Bridges") {
                        ForEach(appState.connectedProviders, id: \.self) { provider in
                            let isActive = provider == appState.activeBridgeProvider
                            let bridge = appState.bridges[provider]
                            HStack {
                                Image(systemName: provider.iconName)
                                    .foregroundStyle(isActive ? Color.accentColor : Color.secondary)
                                    .frame(width: 24)
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(provider.displayName)
                                        .font(.system(size: 14, weight: isActive ? .semibold : .regular))
                                    Text(bridge?.connectionStatus.label ?? "Unknown")
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                }
                                Spacer()
                                if isActive {
                                    Image(systemName: "checkmark.circle.fill")
                                        .foregroundStyle(.tint)
                                }
                            }
                            .contentShape(Rectangle())
                            .onTapGesture {
                                appState.switchToBridge(provider)
                            }
                            .swipeActions(edge: .trailing) {
                                Button(role: .destructive) {
                                    providerToUnpair = provider
                                    showUnpairConfirm = true
                                } label: {
                                    Label("Remove", systemImage: "trash")
                                }
                            }
                        }
                    }
                }

                // MARK: - Setup guides

                Section {
                    setupGuideRow(for: .cmux)
                    setupGuideRow(for: .codex)
                    setupGuideRow(for: .t3code)
                } header: {
                    Text("Setup Guides")
                } footer: {
                    Text("Tap a guide to see how to connect each bridge.")
                        .font(.footnote)
                }

                Section("Quick Actions") {
                    NavigationLink("Manage Quick Actions") {
                        QuickActionSettingsView()
                    }
                }

                Section("Speech Input") {
                    Toggle("Auto-submit speech", isOn: $autoSubmitSpeech)
                    Text("When enabled, automatically presses Enter after sending speech text.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }

                Section {
                    Button("Add Bridge") {
                        appState.isPairingPresented = true
                    }

                    if !appState.bridges.isEmpty {
                        Button("Remove All", role: .destructive) {
                            appState.unpair()
                        }
                    }
                }
            }
            .navigationTitle("Settings")
            .confirmationDialog(
                "Remove \(providerToUnpair?.displayName ?? "bridge")?",
                isPresented: $showUnpairConfirm,
                titleVisibility: .visible
            ) {
                Button("Remove", role: .destructive) {
                    if let provider = providerToUnpair {
                        appState.unpairProvider(provider)
                    }
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("You will need to set up this bridge again to reconnect.")
            }
        }
    }

    // MARK: - Setup guide rows

    @ViewBuilder
    private func setupGuideRow(for provider: BridgeProvider) -> some View {
        let isExpanded = expandedSetupGuide == provider
        let isConnected = appState.bridges[provider] != nil

        VStack(alignment: .leading, spacing: 0) {
            Button {
                withAnimation(.easeInOut(duration: 0.2)) {
                    expandedSetupGuide = isExpanded ? nil : provider
                }
            } label: {
                HStack(spacing: 10) {
                    Image(systemName: provider.iconName)
                        .font(.system(size: 14))
                        .frame(width: 24)
                        .foregroundStyle(isConnected ? Color.accentColor : Color.secondary)

                    VStack(alignment: .leading, spacing: 1) {
                        Text(provider.displayName)
                            .font(.system(size: 14, weight: .medium))
                            .foregroundStyle(.primary)
                        Text(provider.description)
                            .font(.system(size: 11))
                            .foregroundStyle(.secondary)
                    }

                    Spacer()

                    if isConnected {
                        Text("Connected")
                            .font(.system(size: 10, weight: .medium))
                            .foregroundStyle(.green)
                    }

                    Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                        .font(.system(size: 11))
                        .foregroundStyle(.secondary)
                }
            }
            .buttonStyle(.plain)

            if isExpanded {
                Divider()
                    .padding(.vertical, 8)

                setupInstructions(for: provider)
                    .padding(.bottom, 4)
            }
        }
    }

    @ViewBuilder
    private func setupInstructions(for provider: BridgeProvider) -> some View {
        switch provider {
        case .cmux:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install cmux on your Mac")
                codeBlock("brew install cmux")

                instructionStep(2, "Start the bridge with pairing mode")
                codeBlock("cmux-bridge --pair")

                instructionStep(3, "Scan the QR code from this app")
                Text("The QR code contains your connection credentials. Make sure your phone and Mac are on the same network.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(4, "For remote access, add Tailscale")
                codeBlock("cmux-bridge --pair --tailscale")
            }

        case .codex:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install Codex CLI")
                codeBlock("npm install -g @openai/codex")

                instructionStep(2, "Start the app server with WebSocket listener")
                codeBlock("codex app-server --listen ws://0.0.0.0:4080")

                instructionStep(3, "If using auth, note the token")
                codeBlock("codex app-server --listen ws://0.0.0.0:4080 --ws-auth")

                instructionStep(4, "Connect from this app")
                Text("Enter your Mac's IP address, port 4080, and the auth token (if configured). Find your IP with:")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
                codeBlock("ipconfig getifaddr en0")

                infoBox("Codex supports structured approvals \u{2014} you can approve file changes and commands directly from your phone.")
            }

        case .t3code:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install T3 Code")
                codeBlock("brew install --cask t3-code")
                Text("Or download from t3.chat/code")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(2, "Launch T3 Code and open a project")
                Text("T3 Code automatically starts a WebSocket server on port 3773.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(3, "Connect from this app")
                Text("Enter your Mac's IP address and port 3773. No token is needed for local connections.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
                codeBlock("ipconfig getifaddr en0")

                infoBox("T3 Code wraps both Claude and Codex agents. You get multi-agent support, git worktrees, and approval handling from one bridge.")
            }
        }
    }

    private func instructionStep(_ number: Int, _ text: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Text("\(number)")
                .font(.system(size: 10, weight: .bold, design: .monospaced))
                .foregroundStyle(.white)
                .frame(width: 18, height: 18)
                .background(Circle().fill(Color.accentColor))
            Text(text)
                .font(.system(size: 12, weight: .medium))
        }
    }

    private func codeBlock(_ code: String) -> some View {
        Text(code)
            .font(.system(size: 11, design: .monospaced))
            .foregroundStyle(.primary)
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(.systemGray5))
            )
            .textSelection(.enabled)
    }

    private func infoBox(_ text: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Image(systemName: "info.circle.fill")
                .font(.system(size: 12))
                .foregroundStyle(.blue)
            Text(text)
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(Color.blue.opacity(0.08))
        )
    }

    // MARK: - Capabilities

    private var capabilityLabels: [String] {
        let caps = appState.bridgeCapabilities
        var labels: [String] = []
        if caps.contains(.terminalIO) { labels.append("Terminal I/O") }
        if caps.contains(.outputPolling) { labels.append("Polling") }
        if caps.contains(.outputStreaming) { labels.append("Streaming") }
        if caps.contains(.paneLayout) { labels.append("Panes") }
        if caps.contains(.surfaceSplit) { labels.append("Split") }
        if caps.contains(.browserSurfaces) { labels.append("Browser") }
        if caps.contains(.structuredApprovals) { labels.append("Approvals") }
        if caps.contains(.agentStatus) { labels.append("Agent Status") }
        if caps.contains(.fileDiffs) { labels.append("Diffs") }
        if caps.contains(.gitOperations) { labels.append("Git") }
        if caps.contains(.multiAgent) { labels.append("Multi-Agent") }
        return labels
    }
}

