import SwiftUI

struct SettingsView: View {
    @EnvironmentObject var appState: AppState
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @State private var showUnpairConfirm = false
    @State private var providerToUnpair: BridgeProvider?
    @State private var expandedSetupGuide: BridgeProvider?

    var body: some View {
        NavigationStack {
            Form {
                Section("Active Bridge") {
                    if let provider = appState.activeBridgeProvider {
                        HStack {
                            Image(systemName: provider.iconName)
                                .foregroundStyle(.tint)
                            Text(provider.displayName)
                                .font(.headline)
                            Spacer()
                            Text(appState.connectionStatus.label)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }

                        if !appState.bridgeCapabilities.isEmpty {
                            LabeledContent("Capabilities") {
                                Text(capabilityLabels.joined(separator: ", "))
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                        }
                    } else {
                        Text("No bridge connected")
                            .foregroundStyle(.secondary)
                    }

                    if appState.connectedProviders.count > 1 {
                        Button {
                            appState.cycleBridge()
                        } label: {
                            Label("Switch Bridge", systemImage: "arrow.triangle.2.circlepath")
                        }
                    }
                }

                if !appState.connectedProviders.isEmpty {
                    Section("Connected Bridges") {
                        ForEach(appState.connectedProviders, id: \.self) { provider in
                            let isActive = provider == appState.activeBridgeProvider
                            let bridge = appState.bridges[provider]
                            HStack {
                                Image(systemName: provider.iconName)
                                    .foregroundStyle(isActive ? Color.accentColor : Color.secondary)
                                    .frame(width: 24)
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(provider.displayName)
                                        .font(.system(size: 14, weight: isActive ? .semibold : .regular))
                                    Text(bridge?.connectionStatus.label ?? "Unknown")
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                }
                                Spacer()
                                if isActive {
                                    Image(systemName: "checkmark.circle.fill")
                                        .foregroundStyle(.tint)
                                }
                            }
                            .contentShape(Rectangle())
                            .onTapGesture {
                                appState.switchToBridge(provider)
                            }
                            .swipeActions(edge: .trailing) {
                                Button(role: .destructive) {
                                    providerToUnpair = provider
                                    showUnpairConfirm = true
                                } label: {
                                    Label("Remove", systemImage: "trash")
                                }
                            }
                        }
                    }
                }

                // MARK: - Setup guides

                Section {
                    setupGuideRow(for: .cmux)
                    setupGuideRow(for: .codex)
                    setupGuideRow(for: .t3code)
                } header: {
                    Text("Setup Guides")
                } footer: {
                    Text("Tap a guide to see how to connect each bridge.")
                        .font(.footnote)
                }

                Section("Quick Actions") {
                    NavigationLink("Manage Quick Actions") {
                        QuickActionSettingsView()
                    }
                }

                Section("Speech Input") {
                    Toggle("Auto-submit speech", isOn: $autoSubmitSpeech)
                    Text("When enabled, automatically presses Enter after sending speech text.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }

                Section {
                    Button("Add Bridge") {
                        appState.isPairingPresented = true
                    }

                    if !appState.bridges.isEmpty {
                        Button("Remove All", role: .destructive) {
                            appState.unpair()
                        }
                    }
                }
            }
            .navigationTitle("Settings")
            .confirmationDialog(
                "Remove \(providerToUnpair?.displayName ?? "bridge")?",
                isPresented: $showUnpairConfirm,
                titleVisibility: .visible
            ) {
                Button("Remove", role: .destructive) {
                    if let provider = providerToUnpair {
                        appState.unpairProvider(provider)
                    }
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("You will need to set up this bridge again to reconnect.")
            }
        }
    }

    // MARK: - Setup guide rows

    @ViewBuilder
    private func setupGuideRow(for provider: BridgeProvider) -> some View {
        let isExpanded = expandedSetupGuide == provider
        let isConnected = appState.bridges[provider] != nil

        VStack(alignment: .leading, spacing: 0) {
            Button {
                withAnimation(.easeInOut(duration: 0.2)) {
                    expandedSetupGuide = isExpanded ? nil : provider
                }
            } label: {
                HStack(spacing: 10) {
                    Image(systemName: provider.iconName)
                        .font(.system(size: 14))
                        .frame(width: 24)
                        .foregroundStyle(isConnected ? Color.accentColor : Color.secondary)

                    VStack(alignment: .leading, spacing: 1) {
                        Text(provider.displayName)
                            .font(.system(size: 14, weight: .medium))
                            .foregroundStyle(.primary)
                        Text(provider.description)
                            .font(.system(size: 11))
                            .foregroundStyle(.secondary)
                    }

                    Spacer()

                    if isConnected {
                        Text("Connected")
                            .font(.system(size: 10, weight: .medium))
                            .foregroundStyle(.green)
                    }

                    Image(systemName: isExpanded ? "chevron.up" : "chevron.down")
                        .font(.system(size: 11))
                        .foregroundStyle(.secondary)
                }
            }
            .buttonStyle(.plain)

            if isExpanded {
                Divider()
                    .padding(.vertical, 8)

                setupInstructions(for: provider)
                    .padding(.bottom, 4)
            }
        }
    }

    @ViewBuilder
    private func setupInstructions(for provider: BridgeProvider) -> some View {
        switch provider {
        case .cmux:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install cmux on your Mac")
                codeBlock("brew install cmux")

                instructionStep(2, "Start the bridge with pairing mode")
                codeBlock("cmux-bridge --pair")

                instructionStep(3, "Scan the QR code from this app")
                Text("The QR code contains your connection credentials. Make sure your phone and Mac are on the same network.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(4, "For remote access, add Tailscale")
                codeBlock("cmux-bridge --pair --tailscale")
            }

        case .codex:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install Codex CLI")
                codeBlock("npm install -g @openai/codex")

                instructionStep(2, "Start the app server with WebSocket listener")
                codeBlock("codex app-server --listen ws://0.0.0.0:4080")

                instructionStep(3, "If using auth, note the token")
                codeBlock("codex app-server --listen ws://0.0.0.0:4080 --ws-auth")

                instructionStep(4, "Connect from this app")
                Text("Enter your Mac's IP address, port 4080, and the auth token (if configured). Find your IP with:")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
                codeBlock("ipconfig getifaddr en0")

                infoBox("Codex supports structured approvals \u{2014} you can approve file changes and commands directly from your phone.")
            }

        case .t3code:
            VStack(alignment: .leading, spacing: 8) {
                instructionStep(1, "Install T3 Code")
                codeBlock("brew install --cask t3-code")
                Text("Or download from t3.chat/code")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(2, "Start the T3 Code server for remote access")
                Text("The desktop app uses a random port and token. For the companion app, run the server standalone:")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
                codeBlock("node \"/Applications/T3 Code (Alpha).app/Contents/Resources/app.asar/apps/server/dist/index.mjs\" --port 3773 --no-browser --home-dir ~/.t3")
                Text("This shares the same data as the desktop app. No auth token needed.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)

                instructionStep(3, "Connect from this app")
                Text("Enter your Mac's IP address and port 3773.")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
                codeBlock("ipconfig getifaddr en0")

                infoBox("T3 Code wraps both Claude and Codex agents. You get multi-agent support, git worktrees, and approval handling from one bridge.")
            }
        }
    }

    private func instructionStep(_ number: Int, _ text: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Text("\(number)")
                .font(.system(size: 10, weight: .bold, design: .monospaced))
                .foregroundStyle(.white)
                .frame(width: 18, height: 18)
                .background(Circle().fill(Color.accentColor))
            Text(text)
                .font(.system(size: 12, weight: .medium))
        }
    }

    private func codeBlock(_ code: String) -> some View {
        Text(code)
            .font(.system(size: 11, design: .monospaced))
            .foregroundStyle(.primary)
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(.systemGray5))
            )
            .textSelection(.enabled)
    }

    private func infoBox(_ text: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Image(systemName: "info.circle.fill")
                .font(.system(size: 12))
                .foregroundStyle(.blue)
            Text(text)
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(Color.blue.opacity(0.08))
        )
    }

    // MARK: - Capabilities

    private var capabilityLabels: [String] {
        let caps = appState.bridgeCapabilities
        var labels: [String] = []
        if caps.contains(.terminalIO) { labels.append("Terminal I/O") }
        if caps.contains(.outputPolling) { labels.append("Polling") }
        if caps.contains(.outputStreaming) { labels.append("Streaming") }
        if caps.contains(.paneLayout) { labels.append("Panes") }
        if caps.contains(.surfaceSplit) { labels.append("Split") }
        if caps.contains(.browserSurfaces) { labels.append("Browser") }
        if caps.contains(.structuredApprovals) { labels.append("Approvals") }
        if caps.contains(.agentStatus) { labels.append("Agent Status") }
        if caps.contains(.fileDiffs) { labels.append("Diffs") }
        if caps.contains(.gitOperations) { labels.append("Git") }
        if caps.contains(.multiAgent) { labels.append("Multi-Agent") }
        return labels
    }
}

