            }

            Button {
                showScanner = true
            } label: {
                Label("Scan QR Code", systemImage: "qrcode.viewfinder")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)
            .padding(.horizontal)

            Button("Enter manually") {
                showManual = true
            }
            .foregroundStyle(.secondary)

            qrGenerationHint
                .padding(.horizontal, 32)

            Spacer()
        }
        .sheet(isPresented: $showScanner) {
            QRScannerView { scannedURL in
                showScanner = false
                if let url = URL(string: scannedURL) {
                    appState.handlePairingURL(url, providerHint: selectedProvider)
                }
            }
        }
        .sheet(isPresented: $showManual) {
            ManualPairingView(provider: selectedProvider)
        }
    }

    private var pairingInstructions: String {
        switch selectedProvider {
        case .cmux:
            return "Scan the QR code shown by\n`cmux-bridge --pair` on your Mac."
        case .codex:
            return "Scan a QR code or enter connection details for your Codex app-server."
        case .t3code:
            return "Scan a QR code or enter connection details for T3 Code."
        }
    }

    @ViewBuilder
    private var qrGenerationHint: some View {
        VStack(spacing: 6) {
            Text("Generate a QR code on your Mac:")
                .font(.system(size: 11, weight: .medium))
                .foregroundStyle(.secondary)
            Text(qrCommand)
                .font(.system(size: 10, design: .monospaced))
                .foregroundStyle(.primary)
                .padding(.horizontal, 10)
                .padding(.vertical, 6)
                .background(
                    RoundedRectangle(cornerRadius: 6)
                        .fill(Color(.systemGray5))
                )
                .textSelection(.enabled)
        }
    }

    private var qrCommand: String {
        switch selectedProvider {
        case .cmux:
            return "cmux-bridge --pair"
        case .codex:
            return "companion-qr codex --port 4080"
        case .t3code:
            return "companion-qr t3code"
        }
    }
}

private struct ManualPairingView: View {
    let provider: BridgeProvider
    @EnvironmentObject var appState: AppState
    @Environment(\.dismiss) private var dismiss
    @State private var host = ""
    @State private var port: String
    @State private var token = ""
    @State private var didConnect = false

    init(provider: BridgeProvider) {
        self.provider = provider
        _port = State(initialValue: String(provider.defaultPort))
    }

    var body: some View {
        NavigationStack {
            if didConnect {
                connectingView
            } else {
                formView
            }
        }
    }

    private var connectingView: some View {
        VStack(spacing: 20) {
            Spacer()

            let status = appState.bridges[provider]?.connectionStatus

            if status?.isConnected == true {
                Image(systemName: "checkmark.circle.fill")
                    .font(.system(size: 56))
                    .foregroundStyle(.green)
                Text("\(provider.displayName) connected")
                    .font(.title3.bold())
                Text("\(host):\(port)")
                    .font(.caption.monospaced())
                    .foregroundStyle(.secondary)
            } else {
                ProgressView()
                    .scaleEffect(1.2)
                Text("Connecting to \(provider.displayName)\u{2026}")
                    .font(.headline)
                Text("\(host):\(port)")
                    .font(.caption.monospaced())
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Button {
                dismiss()
            } label: {
                Text(status?.isConnected == true ? "Done" : "Continue in background")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)
            .padding(.horizontal)
            .padding(.bottom)
        }
        .navigationTitle(status(appState.bridges[provider]?.connectionStatus))
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button("Close") { dismiss() }
            }
        }
    }

    private func status(_ s: BridgeConnectionStatus?) -> String {
        if s?.isConnected == true { return "Connected" }
        return "Connecting"
    }

    private var formView: some View {
        Form {
            Section("Connection") {
                TextField("Host or IP", text: $host)
                    .keyboardType(.URL)
                    .autocorrectionDisabled()
                    .textInputAutocapitalization(.never)
                TextField("Port", text: $port)
                    .keyboardType(.numberPad)
            }

            Section("Authentication (optional)") {
                TextField(tokenPlaceholder, text: $token)
                    .autocorrectionDisabled()
                    .textInputAutocapitalization(.never)
                Text(tokenHint)
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
            }

            Section {
                Text(connectionHint)
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }
        }
        .navigationTitle("Manual pairing")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button("Cancel") { dismiss() }
            }
            ToolbarItem(placement: .confirmationAction) {
                Button("Connect") {
                    guard let portInt = Int(port), !host.isEmpty else { return }
                    let creds = PairingCredentials(host: host, port: portInt, token: token)
                    try? PairingStore().save(creds, provider: provider)
                    appState.connect(to: creds, provider: provider)
                    withAnimation { didConnect = true }
                }
                .disabled(host.isEmpty)
            }
        }
    }

    private var tokenPlaceholder: String {
        switch provider {
        case .cmux: return "Paste token from cmux-bridge --pair"
        case .codex: return "Bearer token (optional)"
        case .t3code: return ""
        }
    }

    private var tokenHint: String {
        switch provider {
        case .cmux: return "Required. Get it from cmux-bridge --pair."
        case .codex: return "Optional. Only needed if --ws-auth is enabled."
        case .t3code: return "Optional. Not needed when running the server standalone."
        }
    }

    private var connectionHint: String {
        switch provider {
        case .cmux:
            return "Run `cmux-bridge --pair` on your Mac to get the connection details."
        case .codex:
            return "Run `codex app-server --listen ws://0.0.0.0:PORT` to start the WebSocket server."
        case .t3code:
            return "T3 Code runs on localhost:3773 by default. Enter your machine's IP if connecting over the network."
        }
    }
}

