            if let projects = result["projects"] as? [[String: Any]] {
                let groups = projects.compactMap { dict -> SessionGroup? in
                    guard let id = dict["id"] as? String else { return nil }
                    let title = (dict["title"] as? String) ?? id
                    return SessionGroup(id: id, name: title)
                }
                self.cachedProjects = groups
                print("[T3CodeBridge] found \(groups.count) projects")

                if let threads = result["threads"] as? [[String: Any]] {
                    self.cachedThreads = threads
                    print("[T3CodeBridge] found \(threads.count) threads")
                }
                completion(groups)
            } else {
                print("[T3CodeBridge] no projects in snapshot, full result: \(String(describing: result).prefix(500))")
                completion([])
            }
        }
    }

    func selectGroup(_ id: String, completion: (() -> Void)?) {
        // T3 Code doesn't have a "select project" concept — threads are scoped to projects
        completion?()
    }

    func createGroup(name: String?, completion: (() -> Void)?) {
        // Project creation is done through T3 Code's UI
        completion?()
    }

    func closeGroup(_ id: String, completion: (() -> Void)?) {
        completion?()
    }

    // MARK: - Surfaces (Threads / Agents)

    func listSurfaces(groupID: String?, completion: @escaping ([BridgeSurface]) -> Void) {
        // Fetch fresh snapshot for surfaces
        send(method: "orchestration.getSnapshot") { [weak self] result in
            guard let self else { completion([]); return }

            if let threads = result["threads"] as? [[String: Any]] {
                self.cachedThreads = threads
            }
            if let projects = result["projects"] as? [[String: Any]] {
                self.cachedProjects = projects.compactMap { dict -> SessionGroup? in
                    guard let id = dict["id"] as? String else { return nil }
                    return SessionGroup(id: id, name: (dict["title"] as? String) ?? id)
                }
            }

            let threads: [[String: Any]]
            if let projectID = groupID {
                threads = self.cachedThreads.filter { ($0["projectId"] as? String) == projectID }
            } else {
                threads = self.cachedThreads
            }

            let surfaces = threads.compactMap { dict -> BridgeSurface? in
            guard let id = dict["id"] as? String else { return nil }
            let title = (dict["title"] as? String) ?? "Thread"
            let projectID = dict["projectId"] as? String

            // Parse session status
            let session = dict["session"] as? [String: Any]
            let sessionStatus = session?["status"] as? String ?? "idle"
            let providerName = session?["providerName"] as? String ?? ""

            let agentName: String
            if providerName.contains("codex") {
                agentName = "codex"
            } else if providerName.contains("claude") {
                agentName = "claude"
            } else {
                agentName = providerName.isEmpty ? "agent" : providerName
            }

            let agentStatus: AgentStatus
            switch sessionStatus {
            case "running": agentStatus = .working
            case "ready", "idle": agentStatus = .idle
            case "error": agentStatus = .error
            default: agentStatus = .unknown
            }

            return BridgeSurface(
                id: id,
                title: title,
                kind: .agent(AgentInfo(agent: agentName, agentStatus: agentStatus)),
                isFocused: false,
                groupID: projectID
            )
            }
            completion(surfaces)
        }
    }

    func focusSurface(_ id: String, completion: (() -> Void)?) {
        completion?()
    }

    func createSurface(type: String, completion: (() -> Void)?) {
        completion?()
    }

    func closeSurface(_ id: String, completion: (() -> Void)?) {
        let params: [String: Any] = [
            "command": ["type": "thread.delete", "threadId": id]
        ]
        send(method: "orchestration.dispatchCommand", params: params) { _ in
            completion?()
        }
    }

    // MARK: - I/O

    func sendText(_ text: String, to surfaceID: String) {
        let cleanText = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanText.isEmpty else { return }
        print("[T3CodeBridge] sendText to \(surfaceID): \(cleanText.prefix(100))")

        // Start a new turn on the thread
        let params: [String: Any] = [
            "threadId": surfaceID,
            "input": cleanText
        ]
        send(method: "orchestration.dispatchCommand", params: ["command": ["_tag": "thread.turn.start", "threadId": surfaceID, "input": cleanText]]) { result in
            print("[T3CodeBridge] dispatchCommand response: \(result)")
        }
    }

    func sendKey(_ key: String, to surfaceID: String) {
        print("[T3CodeBridge] sendKey '\(key)' to \(surfaceID)")
        if key == "ctrl+c" {
            send(method: "orchestration.dispatchCommand", params: ["command": ["_tag": "thread.turn.interrupt", "threadId": surfaceID]]) { result in
                print("[T3CodeBridge] interrupt response: \(result)")
            }
        } else {
            send(method: "terminal.write", params: ["threadId": surfaceID, "data": key]) { result in
                print("[T3CodeBridge] terminal.write response: \(result)")
            }
        }
    }

    // MARK: - Output reading

    func readOutput(_ surfaceID: String, lines: Int = 50, scrollback: Bool = false, groupID: String? = nil, completion: @escaping (String) -> Void) {
        // Fetch fresh snapshot to get latest messages
        send(method: "orchestration.getSnapshot") { [weak self] result in
            // Update cache
            if let threads = result["threads"] as? [[String: Any]] {
                self?.cachedThreads = threads
            }

            let thread = self?.cachedThreads.first { ($0["id"] as? String) == surfaceID }

            // Try messages array
            if let messages = thread?["messages"] as? [[String: Any]], !messages.isEmpty {
                let text = messages.compactMap { msg -> String? in
                    let role = msg["role"] as? String ?? ""
                    let content = msg["text"] as? String ?? ""
                    guard !content.isEmpty else { return nil }
                    return role == "assistant" ? content : "> \(content)"
                }.joined(separator: "\n\n")
                if !text.isEmpty {
                    completion(text)
                    return
                }
            }

            // Try activities array (more detailed view)
            if let activities = thread?["activities"] as? [[String: Any]], !activities.isEmpty {
                let text = activities.compactMap { act -> String? in
                    let summary = act["summary"] as? String ?? ""
                    let tone = act["tone"] as? String ?? ""
                    guard !summary.isEmpty else { return nil }
                    let prefix = tone == "error" ? "[!] " : ""
                    return prefix + summary
                }.joined(separator: "\n")
                if !text.isEmpty {
                    completion(text)
                    return
                }
            }

            // Show thread title/status if no messages yet
            let title = thread?["title"] as? String ?? ""
            let session = thread?["session"] as? [String: Any]
            let status = session?["status"] as? String ?? "idle"
            completion(title.isEmpty ? "[\(status)]" : "\(title)\n[\(status)]")
        }
    }

    // MARK: - Notifications

    func clearNotifications(completion: (() -> Void)?) {
        completion?()
    }

    // MARK: - Approvals

    func respondToApproval(_ requestID: String, decision: ApprovalDecision, completion: (() -> Void)?) {
        let decisionStr: String
        switch decision {
        case .accept: decisionStr = "accept"
        case .acceptForSession: decisionStr = "acceptForSession"
        case .decline: decisionStr = "decline"
        case .cancel: decisionStr = "cancel"
        }

        let params: [String: Any] = [
            "command": [
                "type": "thread.approval.respond",
                "requestId": requestID,
                "decision": decisionStr
            ]
        ]
        send(method: "orchestration.dispatchCommand", params: params) { _ in
            completion?()
        }
    }

    // MARK: - Quick actions

    func defaultQuickActionCommands() -> [QuickActionCommand] {
        [
            QuickActionCommand(label: "New thread", icon: "plus.message", command: "", section: "AI"),
            QuickActionCommand(label: "Interrupt", icon: "stop.circle", command: "", section: "AI"),
        ]
    }

    /// Alternate between LAN and Tailscale on each reconnect attempt.
    private var useTailscale = false

    // MARK: - Private

    private func startConnection() {
        guard let credentials else {
            print("[T3CodeBridge] no credentials")
            return
        }
        connectionStatus = .connecting
        delegate?.bridgeDidUpdateStatus(self, status: .connecting)

        let host: String
        if useTailscale, let tsHost = credentials.tailscaleHost, !tsHost.isEmpty {
            host = tsHost
        } else {
            host = credentials.host
        }

        var urlString = "ws://\(host):\(credentials.port)/"
        if !credentials.token.isEmpty {
            urlString += "?token=\(credentials.token)"
        }
        print("[T3CodeBridge] connecting to ws://\(host):\(credentials.port)/ (tailscale: \(useTailscale), token: \(credentials.token.isEmpty ? "none" : "***"))")
        guard let url = URL(string: urlString) else {
            print("[T3CodeBridge] invalid URL")
            return
        }

        var request = URLRequest(url: url)
        request.timeoutInterval = useTailscale ? 10 : 5

        let wsDelegate = T3WSDelegate(bridge: self)
        self.wsDelegate = wsDelegate
        let session = URLSession(configuration: .default, delegate: wsDelegate, delegateQueue: nil)
        self.session = session
        let task = session.webSocketTask(with: request)
        self.task = task
        task.resume()
        receiveNext()
    }

    private func receiveNext() {
        task?.receive { [weak self] result in
            guard let self else { return }
            switch result {
            case .success(let message):
                Task { @MainActor in
                    self.handleMessage(message)
                }
                self.receiveNext()
            case .failure(let error):
                print("[T3CodeBridge] receive error: \(error)")
                Task { @MainActor in
                    self.handleDisconnect()
                }
            }
        }
    }

    private func handleMessage(_ message: URLSessionWebSocketTask.Message) {
        if case .string(let text) = message {
            print("[T3CodeBridge] received: \(text.prefix(300))")
        }
        guard case .string(let text) = message,
              let data = text.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return }

        let type = json["type"] as? String

        // Handle push events: {"type":"push","channel":"...","data":{...}}
        if type == "push" {
            let channel = json["channel"] as? String ?? ""
            let eventData = json["data"] as? [String: Any] ?? [:]
            handlePushEvent(channel: channel, data: eventData)
            return
        }

        // Handle RPC response: {"id":"...","body":{...}} or {"id":"...","error":{...}}
        if let id = json["id"] as? String ?? (json["id"] as? Int).map({ String($0) }) {
            if let error = json["error"] as? [String: Any] {
                print("[T3CodeBridge] RPC error for id=\(id): \(error["message"] as? String ?? "unknown")")
                completions.removeValue(forKey: id)?([:]  )
                return
            }
            if let completion = completions.removeValue(forKey: id) {
                // T3 Code wraps response data in "result"
                let result = json["result"] as? [String: Any]
                    ?? json["body"] as? [String: Any]
                    ?? json
                completion(result)
                return
            }
        }
    }

    private func handlePushEvent(channel: String, data: [String: Any]) {
        print("[T3CodeBridge] push channel=\(channel)")

        switch channel {
        case _ where channel.contains("orchestration"):
            let type = data["type"] as? String ?? ""
            print("[T3CodeBridge] orchestration event: \(type)")

            switch type {
            case "request.opened":
                let requestID = data["requestId"] as? String ?? UUID().uuidString
                let summary = data["summary"] as? String ?? "Approval requested"
                let kind = data["requestType"] as? String ?? ""

                let approvalKind: ApprovalKind
                if kind.contains("command") { approvalKind = .command }
                else if kind.contains("file") { approvalKind = .fileChange }
                else { approvalKind = .permission }

                let request = ApprovalRequest(
                    id: requestID,
                    kind: approvalKind,
                    summary: summary,
                    detail: data["detail"] as? String,
                    availableDecisions: [.accept, .acceptForSession, .decline, .cancel]
                )
                delegate?.bridgeDidReceiveApproval(self, request: request)

                let notification = AgentNotification(
                    id: requestID,
                    title: "Approval needed",
                    subtitle: kind,
                    body: summary,
                    surfaceID: data["threadId"] as? String,
                    groupID: data["projectId"] as? String
                )
                delegate?.bridgeDidReceiveNotification(self, notification: notification)

            default:
                // Any orchestration event: refresh surfaces to pick up new threads,
                // state changes, messages, etc.
                refreshSnapshot()
            }

        case _ where channel.contains("terminal"):
            break

        case _ where channel.contains("server"):
            break

        default:
            break
        }
    }

    private func refreshSnapshot() {
        listGroups { [weak self] groups in
            guard let self else { return }
            self.delegate?.bridgeDidUpdateGroups(self, groups: groups)
            // Also refresh surfaces
            self.listSurfaces(groupID: nil) { surfaces in
                self.delegate?.bridgeDidUpdateSurfaces(self, surfaces: surfaces)
            }
        }
    }

    func handleConnected() {
        print("[T3CodeBridge] WebSocket connected")
        backoff = 1
        useTailscale = false
        connectionStatus = .connected
        delegate?.bridgeDidUpdateStatus(self, status: .connected)

        // Subscribe to push channels
        send(method: "subscribeOrchestrationDomainEvents")
        send(method: "subscribeTerminalEvents")
        send(method: "subscribeServerConfig")
        send(method: "subscribeServerLifecycle")

        // Fetch initial snapshot
        refreshSnapshot()
        delegate?.bridgeDidConnect(self)
    }

    func handleDisconnect() {
        task = nil
        connectionStatus = .reconnecting
        delegate?.bridgeDidUpdateStatus(self, status: .reconnecting)
        delegate?.bridgeDidDisconnect(self, error: nil)
        guard shouldReconnect else { return }
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        let delay = backoff
        backoff = min(backoff * 2, 30)
        Task {
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard self.shouldReconnect else { return }
            self.startConnection()
        }
    }

    private func send(
        method: String,
        params: [String: Any] = [:],
        completion: (([String: Any]) -> Void)? = nil
    ) {
        let id = String(nextID)
        nextID += 1

        // Effect RPC format: {"id": "...", "body": {"_tag": "MethodName", ...params}}
        var body: [String: Any] = ["_tag": method]
        for (key, value) in params {
            body[key] = value
        }
        let payload: [String: Any] = ["id": id, "body": body]

        if let completion {
            completions[id] = completion
        }

        guard let data = try? JSONSerialization.data(withJSONObject: payload),
              let task else { return }

        let str = String(data: data, encoding: .utf8)!
        print("[T3CodeBridge] sending: \(str.prefix(200))")
        task.send(.string(str)) { _ in }
    }
}

// MARK: - WebSocket delegate

private final class T3WSDelegate: NSObject, URLSessionWebSocketDelegate {
    weak var bridge: T3CodeBridge?

    init(bridge: T3CodeBridge) {
        self.bridge = bridge
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didOpenWithProtocol proto: String?) {
        Task { @MainActor in
            self.bridge?.handleConnected()
        }
    }

    func urlSession(_ session: URLSession, webSocketTask: URLSessionWebSocketTask, didCloseWith closeCode: URLSessionWebSocketTask.CloseCode, reason: Data?) {
        Task { @MainActor in
            self.bridge?.handleDisconnect()
        }
    }
}

