private struct EditBridgeView: View {
    let provider: BridgeProvider
    @EnvironmentObject var appState: AppState
    @Environment(\.dismiss) private var dismiss
    @State private var host: String
    @State private var port: String
    @State private var token: String

    init(provider: BridgeProvider) {
        self.provider = provider
        let pairing = PairingStore().loadAll().first(where: { $0.provider == provider })
        _host = State(initialValue: pairing?.credentials.host ?? "")
        _port = State(initialValue: pairing.map { String($0.credentials.port) } ?? String(provider.defaultPort))
        _token = State(initialValue: pairing?.credentials.token ?? "")
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    HStack {
                        Image(systemName: provider.iconName)
                            .foregroundStyle(.tint)
                        Text(provider.displayName)
                            .font(.headline)
                    }
                }

                Section("Connection") {
                    TextField("Host or IP", text: $host)
                        .keyboardType(.URL)
                        .autocorrectionDisabled()
                        .textInputAutocapitalization(.never)
                    TextField("Port", text: $port)
                        .keyboardType(.numberPad)
                }

                Section("Authentication") {
                    TextField("Token (optional)", text: $token)
                        .autocorrectionDisabled()
                        .textInputAutocapitalization(.never)
                }

                Section {
                    Button("Reconnect with new settings") {
                        guard let portInt = Int(port), !host.isEmpty else { return }
                        let creds = PairingCredentials(host: host, port: portInt, token: token)
                        appState.connect(to: creds, provider: provider)
                        dismiss()
                    }
                    .disabled(host.isEmpty)
                }
            }
            .navigationTitle("Edit \(provider.displayName)")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
            }
        }
    }
}

