            if hasNotification {
                RoundedRectangle(cornerRadius: 12)
                    .stroke(Color.orange, lineWidth: 2.5)
                    .opacity(notificationPulse ? 0.4 : 1.0)
                    .animation(
                        .easeInOut(duration: 1.2).repeatForever(autoreverses: true),
                        value: notificationPulse
                    )
                    .onAppear { notificationPulse = true }
                    .onDisappear { notificationPulse = false }
            }

            // Focus glow border
            RoundedRectangle(cornerRadius: 12)
                .stroke(borderColor, lineWidth: isFocused ? 1.5 : 0.5)

            // Content
            VStack(spacing: 0) {
                // Title bar
                titleBar

                // Body area
                ZStack(alignment: .topLeading) {
                    if isBrowser {
                        VStack(spacing: 8) {
                            Image(systemName: "globe")
                                .font(.system(size: isFocused ? 28 : 16))
                                .foregroundStyle(.white.opacity(0.2))
                            if !browserURL.isEmpty {
                                Text(browserURL
                                    .replacingOccurrences(of: "https://", with: "")
                                    .replacingOccurrences(of: "http://", with: ""))
                                    .font(.system(size: isFocused ? 10 : 7, design: .monospaced))
                                    .foregroundStyle(.white.opacity(0.4))
                                    .lineLimit(2)
                                    .multilineTextAlignment(.center)
                            }
                            if !title.isEmpty {
                                Text(title)
                                    .font(.system(size: isFocused ? 9 : 7, weight: .medium))
                                    .foregroundStyle(.white.opacity(0.3))
                                    .lineLimit(1)
                            }
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    } else if !terminalText.isEmpty {
                        terminalContentView
                    } else if !isBrowser {
                        // Loading state for terminals before content arrives
                        VStack(spacing: 10) {
                            ProgressView()
                                .scaleEffect(0.7)
                                .tint(.white.opacity(0.3))
                            Text("Loading…")
                                .font(.system(size: 9, weight: .medium, design: .monospaced))
                                .foregroundStyle(.white.opacity(0.2))
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
            }
        }
        .shadow(color: isFocused ? .white.opacity(0.08) : .clear, radius: 12)
    }

    // MARK: - Terminal content

    private var terminalContentView: some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(spacing: 0) {
                    // Pull-to-load indicator (visible when at top and pulling)
                    if isFocused && !hasFullHistory {
                        GeometryReader { geo in
                            let offset = geo.frame(in: .named("termScroll")).minY
                            Color.clear
                                .onChange(of: offset) { _, newOffset in
                                    pullOffset = newOffset
                                    if newOffset > 60 && !hasTriggeredPull && !isLoadingHistory {
                                        hasTriggeredPull = true
                                        onLoadHistory?()
                                    }
                                }
                        }
                        .frame(height: 0)

                        HStack(spacing: 6) {
                            if isLoadingHistory {
                                ProgressView()
                                    .scaleEffect(0.5)
                                    .tint(.white.opacity(0.4))
                                Text("Loading\u{2026}")
                                    .font(.system(size: 8, weight: .medium, design: .monospaced))
                            } else if pullOffset > 10 {
                                Image(systemName: pullOffset > 60 ? "arrow.up.circle.fill" : "arrow.up.circle")
                                    .font(.system(size: 10))
                                    .rotationEffect(.degrees(pullOffset > 60 ? 180 : 0))
                                Text(pullOffset > 60 ? "Release to load" : "Pull for history")
                                    .font(.system(size: 8, weight: .medium, design: .monospaced))
                            }
                        }
                        .foregroundStyle(.white.opacity(0.35))
                        .frame(maxWidth: .infinity)
                        .frame(height: max(0, min(pullOffset, 30)))
                        .clipped()
                        .id("top")
                    }

                    Text(terminalText)
                        .font(.system(size: isFocused ? 9 : 7, weight: .regular, design: .monospaced))
                        .foregroundStyle(.white.opacity(isFocused ? 0.85 : 0.5))
                        .lineSpacing(1)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 8)
                        .padding(.vertical, 6)

                    Color.clear.frame(height: 1).id("bottom")
                }
            }
            .coordinateSpace(name: "termScroll")
            .simultaneousGesture(
                DragGesture(minimumDistance: 3)
                    .onChanged { value in
                        if value.translation.height > 5 {
                            userScrolledUp = true
                        } else if value.translation.height < -5 {
                            userScrolledUp = false
                        }
                    }
                    .onEnded { _ in
                        hasTriggeredPull = false
                        pullOffset = 0
                    }
            )
            .onAppear {
                proxy.scrollTo("bottom", anchor: .bottom)
            }
            .onChange(of: terminalText) {
                if !userScrolledUp {
                    proxy.scrollTo("bottom", anchor: .bottom)
                }
            }
        }
    }

    // MARK: - Title bar

    private var titleBar: some View {
        HStack(spacing: 6) {
            // Surface type icon
            Image(systemName: isBrowser ? "globe" : "terminal")
                .font(.system(size: 9, weight: .medium))
                .foregroundStyle(isFocused ? .white.opacity(0.5) : .white.opacity(0.2))

            // Title
            Text(title.isEmpty ? "untitled" : title)
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(isFocused ? .white.opacity(0.7) : .white.opacity(0.3))
                .lineLimit(1)
                .truncationMode(.middle)

            Spacer()
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .background(
            Rectangle()
                .fill(isFocused ? Color.white.opacity(0.06) : Color.white.opacity(0.02))
        )
        // Top corners only
        .clipShape(
            UnevenRoundedRectangle(
                topLeadingRadius: 12,
                bottomLeadingRadius: 0,
                bottomTrailingRadius: 0,
                topTrailingRadius: 12
            )
        )
    }

    private var borderColor: Color {
        if hasNotification { return Color.orange.opacity(0.6) }
        if isFocused { return Color.white.opacity(0.5) }
        return Color.white.opacity(0.08)
    }
}

import SwiftUI
import AudioToolbox

// MARK: - Quick action model

struct QuickAction: Identifiable {
    let id = UUID()
    let label: String
    let icon: String
    let section: String
    let action: () -> Void
}

enum QuickActionBuilder {
    @MainActor
    static func build(surfaceID sid: String, appState: AppState, store: QuickActionStore, onToggleFullscreen: @escaping () -> Void = {}) -> [QuickAction] {
        let provider = appState.activeBridgeProvider
        var builtIn: [QuickAction] = []

        // Input actions — universal across all bridges
        builtIn += [
            QuickAction(label: "Enter", icon: "return", section: "Input") {
                appState.sendKey("enter", to: sid)
            },
            QuickAction(label: "Ctrl+C", icon: "xmark.circle", section: "Input") {
                appState.sendKey("ctrl+c", to: sid)
            },
            QuickAction(label: "Escape", icon: "escape", section: "Input") {
                appState.sendKey("escape", to: sid)
            },
        ]

        // Terminal-specific input (cmux only)
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "Ctrl+D", icon: "eject", section: "Input") {
                    appState.sendKey("ctrl+d", to: sid)
                },
                QuickAction(label: "Ctrl+Z", icon: "pause.circle", section: "Input") {
                    appState.sendKey("ctrl+z", to: sid)
                },
                QuickAction(label: "Clear", icon: "trash", section: "Input") {
                    appState.sendKey("ctrl+l", to: sid)
                },
                QuickAction(label: "Tab", icon: "arrow.right.to.line", section: "Input") {
                    appState.sendKey("tab", to: sid)
                },
                QuickAction(label: "Up Arrow", icon: "arrow.up", section: "Input") {
                    appState.sendKey("up", to: sid)
                },
                QuickAction(label: "Down Arrow", icon: "arrow.down", section: "Input") {
                    appState.sendKey("down", to: sid)
                },
            ]
        }

        // Terminal/surface management — cmux only
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "Split Right", icon: "rectangle.split.2x1", section: "Terminal") {
                    appState.splitSurface(direction: "right", surfaceID: sid)
                },
                QuickAction(label: "Split Down", icon: "rectangle.split.1x2", section: "Terminal") {
                    appState.splitSurface(direction: "down", surfaceID: sid)
                },
                QuickAction(label: "New Terminal", icon: "plus.rectangle", section: "Terminal") {
                    appState.createSurface()
                },
                QuickAction(label: "Close Surface", icon: "xmark.rectangle", section: "Terminal") {
                    appState.closeSurface(sid)
                },
                QuickAction(label: "Zoom", icon: "arrow.up.left.and.arrow.down.right", section: "Terminal") {
                    appState.togglePaneZoom(sid)
                },
            ]
        }

        // Agent actions — T3 Code
        if provider == .t3code {
            builtIn += [
                QuickAction(label: "Interrupt", icon: "stop.circle", section: "Agent") {
                    appState.sendKey("ctrl+c", to: sid)
                },
                QuickAction(label: "Close Thread", icon: "xmark.rectangle", section: "Agent") {
                    appState.closeSurface(sid)
                },
            ]
        }

        // Agent actions — Codex
        if provider == .codex {
            builtIn += [
                QuickAction(label: "Interrupt", icon: "stop.circle", section: "Agent") {
                    appState.sendKey("ctrl+c", to: sid)
                },
                QuickAction(label: "Close Thread", icon: "xmark.rectangle", section: "Agent") {
                    appState.closeSurface(sid)
                },
            ]
        }

        // Workspace/project actions
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "New Workspace", icon: "square.grid.2x2", section: "Workspace") {
                    appState.createGroup()
                },
                QuickAction(label: "Fullscreen", icon: "rectangle.fill", section: "Workspace") {
                    onToggleFullscreen()
                },
                QuickAction(label: "Close Workspace", icon: "xmark.square", section: "Workspace") {
                    if let wsID = appState.currentGroupID {
                        appState.closeGroup(wsID)
                    }
                },
            ]
        } else {
            builtIn += [
                QuickAction(label: "Fullscreen", icon: "rectangle.fill", section: "View") {
                    onToggleFullscreen()
                },
            ]
        }

        // Multi-bridge: switch bridge action
        if appState.connectedProviders.count > 1 {
            builtIn.append(QuickAction(label: "Switch Bridge", icon: "arrow.triangle.2.circlepath", section: "View") {
                appState.cycleBridge()
            })
        }

        // Filter out hidden built-in actions
        var result = builtIn.filter { !store.isBuiltInHidden($0.label) }

        // Append visible custom actions
        for custom in store.customActions where !custom.isHidden {
            result.append(QuickAction(label: custom.label, icon: custom.icon, section: custom.section) {
                appState.sendText(custom.command, to: sid)
            })
        }

        return result
    }
}

@MainActor
final class QuickActionState: ObservableObject {
    @Published var isOpen = false
    @Published var isFullscreen = false
    @Published var selectedIndex = 0
    @Published var currentSectionIndex = 0
    var actions: [QuickAction] = []

    private static let canonicalOrder = ["Input", "Terminal", "Agent", "Workspace", "View", "AI"]

    var sectionOrder: [String] {
        let present = Set(actions.map(\.section))
        return Self.canonicalOrder.filter { present.contains($0) }
    }

    var currentSection: String {
        guard sectionOrder.indices.contains(currentSectionIndex) else { return sectionOrder[0] }
        return sectionOrder[currentSectionIndex]
    }

    var currentSectionActions: [(Int, QuickAction)] {
        actions.enumerated().filter { $0.element.section == currentSection }.map { ($0.offset, $0.element) }
    }

    func open(with actions: [QuickAction]) {
        self.actions = actions
        currentSectionIndex = 0
        selectedIndex = actions.firstIndex(where: { $0.section == sectionOrder[0] }) ?? 0
        isOpen = true
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
    }

    func dismiss() {
        isOpen = false
        actions = []
    }

    func cycle() {
        let sectionItems = currentSectionActions
        guard !sectionItems.isEmpty else { return }
        if let currentPos = sectionItems.firstIndex(where: { $0.0 == selectedIndex }) {
            let nextPos = (currentPos + 1) % sectionItems.count
            selectedIndex = sectionItems[nextPos].0
        } else {
            selectedIndex = sectionItems[0].0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func nextSection() {
        currentSectionIndex = (currentSectionIndex + 1) % sectionOrder.count
        // Select first item in new section
        if let first = currentSectionActions.first {
            selectedIndex = first.0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func prevSection() {
        currentSectionIndex = (currentSectionIndex - 1 + sectionOrder.count) % sectionOrder.count
        if let first = currentSectionActions.first {
            selectedIndex = first.0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func execute() {
        guard actions.indices.contains(selectedIndex) else { return }
        actions[selectedIndex].action()
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        dismiss()
    }
}

struct WorkspaceLayoutView: View {
    @EnvironmentObject var appState: AppState
    @EnvironmentObject var quickActionStore: QuickActionStore
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @StateObject private var volumeHandler = VolumeButtonHandler()
    @StateObject private var speechManager = SpeechInputManager()
    @StateObject private var quickAction = QuickActionState()
    @State private var lastNotificationCount = 0
    @State private var cycleDirection: Edge = .trailing
    @State private var isEditingTranscript = false
    @State private var editingText = ""
    @State private var contentPollTimer: Timer?
    @State private var fullHistorySurfaces: Set<String> = []
    @State private var loadingHistory: Set<String> = []

    var body: some View {
        ZStack {
            // Background with subtle center glow
            Color.black.ignoresSafeArea()
            RadialGradient(
                colors: [Color.white.opacity(0.03), Color.clear],
                center: .center,
                startRadius: 50,
                endRadius: 400
            )
            .ignoresSafeArea()

            VStack(spacing: 0) {
                if appState.surfaces.isEmpty {
                    emptyState
                } else {
                    surfaceLayout
                }

                if !quickAction.isFullscreen {
                    workspaceBar
                        .padding(.bottom, 4)
                }
            }

            // Speech transcript overlay
            if speechManager.isRecording {
                VStack {
                    Spacer()
                    if !speechManager.transcript.isEmpty {
                        HStack {
                            Text(speechManager.transcript)
                                .font(.system(size: 13, weight: .regular, design: .monospaced))
                                .foregroundStyle(.green)
                                .lineLimit(4)
                                .padding(.horizontal, 14)
                                .padding(.vertical, 10)
                                .background(
                                    RoundedRectangle(cornerRadius: 10)
                                        .fill(.ultraThinMaterial)
                                        .environment(\.colorScheme, .dark)
                                )
                                .overlay(
                                    RoundedRectangle(cornerRadius: 10)
                                        .stroke(Color.green.opacity(0.3), lineWidth: 1)
                                )
                            Spacer()
                        }
                        .padding(.horizontal, 16)
                    }
                }
                .padding(.bottom, 44)
            }

            // Quick action overlay
            if quickAction.isOpen {
                quickActionOverlay
            }
        }
        .fullScreenCover(isPresented: $isEditingTranscript) {
            TranscriptEditorView(
                isPresented: $isEditingTranscript,
                text: editingText
            ) { finalText in
                if !finalText.isEmpty, let surfaceID = appState.focusedSurfaceID {
                    let toSend = autoSubmitSpeech ? finalText + "\n" : finalText
                    appState.sendText(toSend, to: surfaceID)
                }
            }
        }
        .animation(.spring(response: 0.25, dampingFraction: 0.85), value: quickAction.isOpen)
        .onChange(of: appState.notifications.count) { oldCount, newCount in
            if newCount > oldCount {
                AudioServicesPlaySystemSound(1007)
                AudioServicesPlaySystemSound(kSystemSoundID_Vibrate)
                // Auto-clear notifications on focused surface after 3s
                DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
                    appState.clearNotificationsForFocusedSurface()
                }
            }
            lastNotificationCount = newCount
        }
        .onChange(of: appState.focusedSurfaceID) { _, _ in
            // Clear notifications for newly focused surface after a moment
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                appState.clearNotificationsForFocusedSurface()
            }
        }
        .onAppear {
            appState.refreshSurfaces()
            speechManager.requestPermissions()
            wireVolumeCallbacks()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                volumeHandler.start()
            }
            startContentPolling()
        }
        .onDisappear {
            contentPollTimer?.invalidate()
            contentPollTimer = nil
        }
        .onReceive(NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)) { _ in
            // Restart volume handler — iOS can deactivate AVAudioSession
            // when backgrounded, interrupted, or idle, killing the KVO observer
            volumeHandler.start()
            appState.refreshSurfaces()
        }
    }

    // MARK: - Quick actions

    private func openQuickActions() {
        guard let surface = focusedSurface else { return }
        quickAction.open(with: QuickActionBuilder.build(surfaceID: surface.id, appState: appState, store: quickActionStore, onToggleFullscreen: { [quickAction] in quickAction.isFullscreen.toggle() }))
    }

    private var quickActionOverlay: some View {
        ZStack {
            Color.black.opacity(0.6)
                .ignoresSafeArea()
                .contentShape(Rectangle())
                .onTapGesture { quickAction.dismiss() }
                .gesture(
                    DragGesture(minimumDistance: 30)
                        .onEnded { value in
                            withAnimation(.easeInOut(duration: 0.2)) {
                                if value.translation.width < -30 || value.translation.height < -30 {
                                    quickAction.nextSection()
                                } else if value.translation.width > 30 || value.translation.height > 30 {
                                    quickAction.prevSection()
                                }
                            }
                        }
                )

            VStack(spacing: 0) {
                // Section tabs
                HStack(spacing: 0) {
                    ForEach(Array(quickAction.sectionOrder.enumerated()), id: \.element) { idx, section in
                        let isActive = idx == quickAction.currentSectionIndex
                        Button {
                            withAnimation(.easeInOut(duration: 0.2)) {
                                quickAction.currentSectionIndex = idx
                                if let first = quickAction.currentSectionActions.first {
                                    quickAction.selectedIndex = first.0
                                }
                            }
                        } label: {
                            Text(section.uppercased())
                                .font(.system(size: 10, weight: .bold, design: .monospaced))
                                .foregroundStyle(isActive ? .white : .white.opacity(0.3))
                                .frame(maxWidth: .infinity)
                                .padding(.vertical, 10)
                                .overlay(alignment: .bottom) {
                                    if isActive {
                                        Rectangle()
                                            .fill(Color.white)
                                            .frame(height: 2)
                                    }
                                }
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(.horizontal, 8)

                // Current section tiles
                let sectionItems = quickAction.currentSectionActions
                let columns = Array(repeating: GridItem(.flexible(), spacing: 8), count: min(sectionItems.count, 5))

                LazyVGrid(columns: columns, spacing: 8) {
                    ForEach(sectionItems, id: \.0) { index, action in
                        let isSelected = index == quickAction.selectedIndex
                        Button {
                            quickAction.selectedIndex = index
                            quickAction.execute()
                            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                                appState.refreshSurfaces()
                            }
                        } label: {
                            VStack(spacing: 5) {
                                Image(systemName: action.icon)
                                    .font(.system(size: 16))
                                Text(action.label)
                                    .font(.system(size: 9, weight: .medium, design: .monospaced))
                                    .lineLimit(1)
                                    .minimumScaleFactor(0.7)
                            }
                            .foregroundStyle(isSelected ? .white : .white.opacity(0.5))
                            .frame(maxWidth: .infinity)
                            .frame(height: 56)
                            .background(
                                RoundedRectangle(cornerRadius: 10)
                                    .fill(isSelected ? Color.white.opacity(0.2) : Color.white.opacity(0.05))
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: 10)
                                    .stroke(isSelected ? Color.white.opacity(0.4) : .clear, lineWidth: 1)
                            )
                        }
                        .buttonStyle(.plain)
                    }
                }
                .padding(12)
                .animation(.easeInOut(duration: 0.2), value: quickAction.currentSectionIndex)

                // Hints
                HStack(spacing: 16) {
                    hintLabel(key: "VOL-", label: "cycle")
                    hintLabel(key: "VOL+", label: "select")
                    hintLabel(key: "SWIPE", label: "section")
                    hintLabel(key: "2xDN", label: "close")
                }
                .foregroundStyle(.white.opacity(0.2))
                .padding(.bottom, 10)
            }
            .frame(maxWidth: 420)
            .background(
                RoundedRectangle(cornerRadius: 16)
                    .fill(.ultraThinMaterial)
                    .environment(\.colorScheme, .dark)
            )
        }
        .transition(.opacity)
    }

    private func hintLabel(key: String, label: String) -> some View {
        HStack(spacing: 3) {
            Text(key).font(.system(size: 9, weight: .bold, design: .monospaced))
            Text(label).font(.system(size: 9, design: .monospaced))
        }
    }

    // MARK: - Surface layout

    private var focusedSurface: BridgeSurface? {
        appState.surfaces.first(where: { $0.id == appState.focusedSurfaceID })
            ?? appState.surfaces.first
    }

    private var secondarySurfaces: [BridgeSurface] {
        guard let focused = focusedSurface else { return [] }
        return appState.surfaces.filter { $0.id != focused.id }
    }

    private var surfaceLayout: some View {
        GeometryReader { geo in
            let hasSidebar = secondarySurfaces.count > 0 && !quickAction.isFullscreen
            let mainWidth = hasSidebar ? geo.size.width * 0.65 : geo.size.width
            let sideWidth = geo.size.width * 0.35

            HStack(spacing: 8) {
                // Focused surface — large card
                if let surface = focusedSurface {
                    PaneCardView(
                        title: surface.title,
                        isFocused: true,
                        hasNotification: appState.hasNotification(for: surface),
                        terminalText: surface.isBrowser ? "" : (appState.surfaceContent[surface.id] ?? ""),
                        isBrowser: surface.isBrowser,
                        browserURL: appState.browserURLs[surface.id] ?? "",
                        hasFullHistory: fullHistorySurfaces.contains(surface.id),
                        isLoadingHistory: loadingHistory.contains(surface.id),
                        onLoadHistory: { [surface] in
                            loadHistory(for: surface.id)
                        }
                    )
                    .id(surface.id)
                    .frame(width: mainWidth - (hasSidebar ? 4 : 16))
                    .transition(.asymmetric(
                        insertion: .move(edge: cycleDirection).combined(with: .opacity),
                        removal: .move(edge: cycleDirection == .trailing ? .leading : .trailing).combined(with: .opacity)
                    ))
                    .onLongPressGesture(minimumDuration: 0.4) {
                        openQuickActions()
                    }
                    .highPriorityGesture(
                        DragGesture(minimumDistance: 50)
                            .onEnded { value in
                                guard !quickAction.isOpen else { return }
                                if speechManager.isRecording {
                                    // Swipe while recording opens transcript editor
                                    editingText = speechManager.stop()
                                    volumeHandler.clearSpeechState()
                                    isEditingTranscript = true
                                    return
                                }
                                if value.translation.width < -50 {
                                    cycleDirection = .trailing
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.cycleSurface()
                                    }
                                } else if value.translation.width > 50 {
                                    cycleDirection = .leading
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.cycleSurfaceBackward()
                                    }
                                }
                            },
                        including: .gesture
                    )
                }

                // Secondary tiles
                if hasSidebar {
                    ScrollView(.vertical, showsIndicators: false) {
                        VStack(spacing: 6) {
                            ForEach(secondarySurfaces) { surface in
                                PaneCardView(
                                    title: surface.title,
                                    isFocused: false,
                                    hasNotification: appState.hasNotification(for: surface),
                                    terminalText: surface.isBrowser ? "" : (appState.surfaceContent[surface.id] ?? ""),
                                    isBrowser: surface.isBrowser,
                                    browserURL: appState.browserURLs[surface.id] ?? ""
                                )
                                .frame(height: tileHeight(for: secondarySurfaces.count, in: geo.size.height))
                                .onTapGesture {
                                    cycleDirection = .trailing
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.focusSurface(surface.id)
                                    }
                                }
                                .gesture(
                                    DragGesture(minimumDistance: 30)
                                        .onEnded { value in
                                            if value.translation.height < -30 {
                                                withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                                    appState.focusSurface(surface.id)
                                                }
                                            }
                                        }
                                )
                            }
                        }
                    }
                    .frame(width: sideWidth - 4)
                }
            }
            .padding(.horizontal, 12)
            .padding(.top, 8)
        }
    }

    private func tileHeight(for count: Int, in totalHeight: CGFloat) -> CGFloat {
        let available = totalHeight - 52
        let spacing = CGFloat(max(0, count - 1)) * 6
        return max(60, (available - spacing) / CGFloat(count))
    }

    // MARK: - Empty state

    private var emptyState: some View {
        VStack(spacing: 12) {
            Image(systemName: "square.split.2x1")
                .font(.system(size: 32, weight: .thin))
                .foregroundStyle(.white.opacity(0.2))
            Text("No surfaces")
                .font(.system(size: 14, weight: .medium))
                .foregroundStyle(.white.opacity(0.3))
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    // MARK: - Workspace bar

    private var workspaceBar: some View {
        HStack(spacing: 0) {
            // Bridge indicator (tap to cycle between bridges)
            if appState.connectedProviders.count > 1 {
                Button {
                    appState.cycleBridge()
                } label: {
                    HStack(spacing: 4) {
                        statusDot
                        if let provider = appState.activeBridgeProvider {
                            Text(provider.displayName.uppercased())
                                .font(.system(size: 8, weight: .bold, design: .monospaced))
                                .foregroundStyle(.white.opacity(0.5))
                        }
                    }
                }
                .buttonStyle(.plain)
                .padding(.leading, 12)
                .padding(.trailing, 8)
            } else {
                statusDot
                    .padding(.leading, 16)
                    .padding(.trailing, 12)
            }

            workspacePills

            HStack(spacing: 10) {
                if speechManager.isRecording {
                    Circle()
                        .fill(Color.red)
                        .frame(width: 8, height: 8)
                        .shadow(color: .red.opacity(0.6), radius: 4)
                    Text("REC")
                        .font(.system(size: 10, weight: .bold, design: .monospaced))
                        .foregroundStyle(.red)
                }

                Button {
                    appState.refreshSurfaces()
                } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.system(size: 12))
                        .foregroundStyle(.white.opacity(0.4))
                }
            }
            .padding(.trailing, 16)
            .padding(.leading, 12)
        }
        .frame(height: 36)
    }

    // MARK: - Workspace pills

    private func groupLabel(for group: SessionGroup, at index: Int) -> String {
        let name = group.name
        if name == group.id || name.allSatisfy({ $0.isHexDigit || $0 == "-" }) {
            return "\(appState.groupLabel) \(index + 1)"
        }
        return name
    }

    private func groupHasNotification(_ group: SessionGroup) -> Bool {
        appState.notifications.contains { $0.groupID == group.id }
    }

    private var workspacePills: some View {
        ScrollViewReader { proxy in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(Array(appState.groups.enumerated()), id: \.element.id) { index, ws in
                        let isActive = ws.id == appState.currentGroupID
                        let hasNotif = groupHasNotification(ws)

                        Button {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.85)) {
                                appState.selectGroup(ws.id)
                            }
                        } label: {
                            Text(groupLabel(for: ws, at: index))
                                .font(.system(size: 11, weight: .medium, design: .monospaced))
                                .foregroundStyle(isActive ? .black : .white.opacity(0.5))
                                .padding(.horizontal, 12)
                                .padding(.vertical, 4)
                                .background(
                                    Capsule()
                                        .fill(isActive ? Color.white : Color.white.opacity(0.08))
                                )
                                .overlay(
                                    Capsule()
                                        .stroke(Color.orange, lineWidth: hasNotif ? 1.5 : 0)
                                )
                        }
                        .buttonStyle(.plain)
                        .id(ws.id)
                    }
                }
                .padding(.horizontal, 8)
            }
            .onChange(of: appState.currentGroupID) { _, newID in
                if let id = newID {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        proxy.scrollTo(id, anchor: .center)
                    }
                }
                fullHistorySurfaces.removeAll()
                loadingHistory.removeAll()
            }
        }
    }

    private var statusDot: some View {
        let color: Color = {
            switch appState.connectionStatus {
            case .connected(true): return .green
            case .connected(false): return .yellow
            case .reconnecting, .connecting: return .yellow
            case .disconnected: return .red
            }
        }()
        return Circle()
            .fill(color)
            .frame(width: 6, height: 6)
            .shadow(color: color.opacity(0.5), radius: 3)
    }

    // MARK: - Content polling

    @State private var pollCycleCount = 0

    private func startContentPolling() {
        // Initial fetch — focused only
        if let focused = focusedSurface {
            fetchContent(for: focused)
        }
        contentPollTimer = Timer.scheduledTimer(withTimeInterval: 3.0, repeats: true) { [weak appState] _ in
            Task { @MainActor in
                guard let appState else { return }
                self.pollCycleCount += 1
                let focusedID = appState.focusedSurfaceID
                // Focused surface every cycle, secondary every 5th (~15s)
                for surface in appState.surfaces {
                    if surface.id == focusedID {
                        self.fetchContent(for: surface)
                    } else if self.pollCycleCount % 5 == 0 {
                        self.fetchContent(for: surface)
                    }
                }
            }
        }
    }

    private func fetchContent(for surface: BridgeSurface) {
        if surface.isBrowser {
            appState.readBrowserURL(surface.id)
        } else {
            appState.readSurfaceText(surface.id, scrollback: fullHistorySurfaces.contains(surface.id))
        }
    }

    private func loadHistory(for surfaceID: String) {
        guard !loadingHistory.contains(surfaceID) else { return }
        let previousLength = appState.surfaceContent[surfaceID]?.count ?? 0
        loadingHistory.insert(surfaceID)
        appState.readSurfaceText(surfaceID, scrollback: true)

        // Poll until content actually changes or timeout after 5s
        DispatchQueue.main.asyncAfter(deadline: .now() + 5) {
            loadingHistory.remove(surfaceID)
            fullHistorySurfaces.insert(surfaceID)
        }
        // Also check sooner if content changed
        DispatchQueue.main.asyncAfter(deadline: .now() + 1) {
            if (appState.surfaceContent[surfaceID]?.count ?? 0) != previousLength {
                loadingHistory.remove(surfaceID)
                fullHistorySurfaces.insert(surfaceID)
            }
        }
    }

    // MARK: - Volume callbacks

    private func wireVolumeCallbacks() {
        let appState = appState
        let speech = speechManager
        let qa = quickAction
        let store = quickActionStore

        let volHandler = volumeHandler
        volumeHandler.onSingleDown = {
            print("[VolumeHandler] singleDown")
            Task { @MainActor in
                if speech.isRecording {
                    speech.cancel()
                    volHandler.clearSpeechState()
                    let generator = UIImpactFeedbackGenerator(style: .light)
                    generator.impactOccurred()
                } else if qa.isOpen {
                    qa.cycle()
                } else {
                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                        appState.cycleSurface()
                    }
                }
            }
        }
        volumeHandler.onDoubleDown = {
            print("[VolumeHandler] doubleDown")
            Task { @MainActor in
                if qa.isOpen {
                    qa.dismiss()
                } else {
                    withAnimation(.spring(response: 0.3, dampingFraction: 0.85)) {
                        appState.cycleGroup()
                    }
                }
            }
        }
        volumeHandler.onSingleUp = {
            print("[VolumeHandler] singleUp")
            Task { @MainActor in
                if qa.isOpen {
                    // Confirm selected action
                    qa.execute()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        appState.refreshSurfaces()
                    }
                } else if speech.isRecording {
                    // Stop recording and send
                    let pending = speech.transcript
                    try? await Task.sleep(nanoseconds: 300_000_000)
                    let text = speech.stop()
                    let finalText = text.isEmpty ? pending : text
                    print("[Speech] sending: \(finalText)")
                    if !finalText.isEmpty, let surfaceID = appState.focusedSurfaceID {
                        let autoSubmit = UserDefaults.standard.bool(forKey: "autoSubmitSpeech")
                        let toSend = autoSubmit ? finalText + "\n" : finalText
                        appState.sendText(toSend, to: surfaceID)
                    }
                } else {
                    // Start recording
                    speech.start()
                }
            }
        }
        volumeHandler.onDoubleUp = {
            print("[VolumeHandler] doubleUp → quickActions")
            Task { @MainActor in
                if qa.isOpen {
                    qa.dismiss()
                } else if let surface = appState.surfaces.first(where: { $0.id == appState.focusedSurfaceID })
                            ?? appState.surfaces.first {
                    let sid = surface.id
                    qa.open(with: QuickActionBuilder.build(surfaceID: sid, appState: appState, store: store, onToggleFullscreen: { qa.isFullscreen.toggle() }))
                }
            }
        }
    }
}

import SwiftUI
import AudioToolbox

// MARK: - Quick action model

struct QuickAction: Identifiable {
    let id = UUID()
    let label: String
    let icon: String
    let section: String
    let action: () -> Void
}

enum QuickActionBuilder {
    @MainActor
    static func build(surfaceID sid: String, appState: AppState, store: QuickActionStore, onToggleFullscreen: @escaping () -> Void = {}) -> [QuickAction] {
        let provider = appState.activeBridgeProvider
        var builtIn: [QuickAction] = []

        // Input actions — universal across all bridges
        builtIn += [
            QuickAction(label: "Enter", icon: "return", section: "Input") {
                appState.sendKey("enter", to: sid)
            },
            QuickAction(label: "Ctrl+C", icon: "xmark.circle", section: "Input") {
                appState.sendKey("ctrl+c", to: sid)
            },
            QuickAction(label: "Escape", icon: "escape", section: "Input") {
                appState.sendKey("escape", to: sid)
            },
        ]

        // Terminal-specific input (cmux only)
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "Ctrl+D", icon: "eject", section: "Input") {
                    appState.sendKey("ctrl+d", to: sid)
                },
                QuickAction(label: "Ctrl+Z", icon: "pause.circle", section: "Input") {
                    appState.sendKey("ctrl+z", to: sid)
                },
                QuickAction(label: "Clear", icon: "trash", section: "Input") {
                    appState.sendKey("ctrl+l", to: sid)
                },
                QuickAction(label: "Tab", icon: "arrow.right.to.line", section: "Input") {
                    appState.sendKey("tab", to: sid)
                },
                QuickAction(label: "Up Arrow", icon: "arrow.up", section: "Input") {
                    appState.sendKey("up", to: sid)
                },
                QuickAction(label: "Down Arrow", icon: "arrow.down", section: "Input") {
                    appState.sendKey("down", to: sid)
                },
            ]
        }

        // Terminal/surface management — cmux only
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "Split Right", icon: "rectangle.split.2x1", section: "Terminal") {
                    appState.splitSurface(direction: "right", surfaceID: sid)
                },
                QuickAction(label: "Split Down", icon: "rectangle.split.1x2", section: "Terminal") {
                    appState.splitSurface(direction: "down", surfaceID: sid)
                },
                QuickAction(label: "New Terminal", icon: "plus.rectangle", section: "Terminal") {
                    appState.createSurface()
                },
                QuickAction(label: "Close Surface", icon: "xmark.rectangle", section: "Terminal") {
                    appState.closeSurface(sid)
                },
                QuickAction(label: "Zoom", icon: "arrow.up.left.and.arrow.down.right", section: "Terminal") {
                    appState.togglePaneZoom(sid)
                },
            ]
        }

        // Agent actions — T3 Code
        if provider == .t3code {
            builtIn += [
                QuickAction(label: "Interrupt", icon: "stop.circle", section: "Agent") {
                    appState.sendKey("ctrl+c", to: sid)
                },
                QuickAction(label: "Close Thread", icon: "xmark.rectangle", section: "Agent") {
                    appState.closeSurface(sid)
                },
            ]
        }

        // Agent actions — Codex
        if provider == .codex {
            builtIn += [
                QuickAction(label: "Interrupt", icon: "stop.circle", section: "Agent") {
                    appState.sendKey("ctrl+c", to: sid)
                },
                QuickAction(label: "Close Thread", icon: "xmark.rectangle", section: "Agent") {
                    appState.closeSurface(sid)
                },
            ]
        }

        // Workspace/project actions
        if provider == .cmux {
            builtIn += [
                QuickAction(label: "New Workspace", icon: "square.grid.2x2", section: "Workspace") {
                    appState.createGroup()
                },
                QuickAction(label: "Fullscreen", icon: "rectangle.fill", section: "Workspace") {
                    onToggleFullscreen()
                },
                QuickAction(label: "Close Workspace", icon: "xmark.square", section: "Workspace") {
                    if let wsID = appState.currentGroupID {
                        appState.closeGroup(wsID)
                    }
                },
            ]
        } else {
            builtIn += [
                QuickAction(label: "Fullscreen", icon: "rectangle.fill", section: "View") {
                    onToggleFullscreen()
                },
            ]
        }

        // Multi-bridge: switch bridge action
        if appState.connectedProviders.count > 1 {
            builtIn.append(QuickAction(label: "Switch Bridge", icon: "arrow.triangle.2.circlepath", section: "View") {
                appState.cycleBridge()
            })
        }

        // Filter out hidden built-in actions
        var result = builtIn.filter { !store.isBuiltInHidden($0.label) }

        // Append visible custom actions
        for custom in store.customActions where !custom.isHidden {
            result.append(QuickAction(label: custom.label, icon: custom.icon, section: custom.section) {
                appState.sendText(custom.command, to: sid)
            })
        }

        return result
    }
}

@MainActor
final class QuickActionState: ObservableObject {
    @Published var isOpen = false
    @Published var isFullscreen = false
    @Published var selectedIndex = 0
    @Published var currentSectionIndex = 0
    var actions: [QuickAction] = []

    private static let canonicalOrder = ["Input", "Terminal", "Agent", "Workspace", "View", "AI"]

    var sectionOrder: [String] {
        let present = Set(actions.map(\.section))
        return Self.canonicalOrder.filter { present.contains($0) }
    }

    var currentSection: String {
        guard sectionOrder.indices.contains(currentSectionIndex) else { return sectionOrder[0] }
        return sectionOrder[currentSectionIndex]
    }

    var currentSectionActions: [(Int, QuickAction)] {
        actions.enumerated().filter { $0.element.section == currentSection }.map { ($0.offset, $0.element) }
    }

    func open(with actions: [QuickAction]) {
        self.actions = actions
        currentSectionIndex = 0
        selectedIndex = actions.firstIndex(where: { $0.section == sectionOrder[0] }) ?? 0
        isOpen = true
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
    }

    func dismiss() {
        isOpen = false
        actions = []
    }

    func cycle() {
        let sectionItems = currentSectionActions
        guard !sectionItems.isEmpty else { return }
        if let currentPos = sectionItems.firstIndex(where: { $0.0 == selectedIndex }) {
            let nextPos = (currentPos + 1) % sectionItems.count
            selectedIndex = sectionItems[nextPos].0
        } else {
            selectedIndex = sectionItems[0].0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func nextSection() {
        currentSectionIndex = (currentSectionIndex + 1) % sectionOrder.count
        // Select first item in new section
        if let first = currentSectionActions.first {
            selectedIndex = first.0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func prevSection() {
        currentSectionIndex = (currentSectionIndex - 1 + sectionOrder.count) % sectionOrder.count
        if let first = currentSectionActions.first {
            selectedIndex = first.0
        }
        UISelectionFeedbackGenerator().selectionChanged()
    }

    func execute() {
        guard actions.indices.contains(selectedIndex) else { return }
        actions[selectedIndex].action()
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        dismiss()
    }
}

struct WorkspaceLayoutView: View {
    @EnvironmentObject var appState: AppState
    @EnvironmentObject var quickActionStore: QuickActionStore
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @StateObject private var volumeHandler = VolumeButtonHandler()
    @StateObject private var speechManager = SpeechInputManager()
    @StateObject private var quickAction = QuickActionState()
    @State private var lastNotificationCount = 0
    @State private var cycleDirection: Edge = .trailing
    @State private var isEditingTranscript = false
    @State private var editingText = ""
    @State private var contentPollTimer: Timer?
    @State private var fullHistorySurfaces: Set<String> = []
    @State private var loadingHistory: Set<String> = []

    var body: some View {
        ZStack {
            // Background with subtle center glow
            Color.black.ignoresSafeArea()
            RadialGradient(
                colors: [Color.white.opacity(0.03), Color.clear],
                center: .center,
                startRadius: 50,
                endRadius: 400
            )
            .ignoresSafeArea()

            VStack(spacing: 0) {
                if appState.surfaces.isEmpty {
                    emptyState
                } else {
                    surfaceLayout
                }

                if !quickAction.isFullscreen {
                    workspaceBar
                        .padding(.bottom, 4)
                }
            }

            // Speech transcript overlay
            if speechManager.isRecording {
                VStack {
                    Spacer()
                    if !speechManager.transcript.isEmpty {
                        HStack {
                            Text(speechManager.transcript)
                                .font(.system(size: 13, weight: .regular, design: .monospaced))
                                .foregroundStyle(.green)
                                .lineLimit(4)
                                .padding(.horizontal, 14)
                                .padding(.vertical, 10)
                                .background(
                                    RoundedRectangle(cornerRadius: 10)
                                        .fill(.ultraThinMaterial)
                                        .environment(\.colorScheme, .dark)
                                )
                                .overlay(
                                    RoundedRectangle(cornerRadius: 10)
                                        .stroke(Color.green.opacity(0.3), lineWidth: 1)
                                )
                            Spacer()
                        }
                        .padding(.horizontal, 16)
                    }
                }
                .padding(.bottom, 44)
            }

            // Quick action overlay
            if quickAction.isOpen {
                quickActionOverlay
            }
        }
        .fullScreenCover(isPresented: $isEditingTranscript) {
            TranscriptEditorView(
                isPresented: $isEditingTranscript,
                text: editingText
            ) { finalText in
                if !finalText.isEmpty, let surfaceID = appState.focusedSurfaceID {
                    let toSend = autoSubmitSpeech ? finalText + "\n" : finalText
                    appState.sendText(toSend, to: surfaceID)
                }
            }
        }
        .animation(.spring(response: 0.25, dampingFraction: 0.85), value: quickAction.isOpen)
        .onChange(of: appState.notifications.count) { oldCount, newCount in
            if newCount > oldCount {
                AudioServicesPlaySystemSound(1007)
                AudioServicesPlaySystemSound(kSystemSoundID_Vibrate)
                // Auto-clear notifications on focused surface after 3s
                DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
                    appState.clearNotificationsForFocusedSurface()
                }
            }
            lastNotificationCount = newCount
        }
        .onChange(of: appState.focusedSurfaceID) { _, _ in
            // Clear notifications for newly focused surface after a moment
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                appState.clearNotificationsForFocusedSurface()
            }
        }
        .onAppear {
            appState.refreshSurfaces()
            speechManager.requestPermissions()
            wireVolumeCallbacks()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                volumeHandler.start()
            }
            startContentPolling()
        }
        .onDisappear {
            contentPollTimer?.invalidate()
            contentPollTimer = nil
        }
        .onReceive(NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)) { _ in
            // Restart volume handler — iOS can deactivate AVAudioSession
            // when backgrounded, interrupted, or idle, killing the KVO observer
            volumeHandler.start()
            appState.refreshSurfaces()
        }
    }

    // MARK: - Quick actions

    private func openQuickActions() {
        guard let surface = focusedSurface else { return }
        quickAction.open(with: QuickActionBuilder.build(surfaceID: surface.id, appState: appState, store: quickActionStore, onToggleFullscreen: { [quickAction] in quickAction.isFullscreen.toggle() }))
    }

