/// Polls SpeechInputManager state on a fast timer to guarantee
/// real-time transcript display regardless of SwiftUI observation issues
/// caused by heavy AppState @Published traffic from bridge polling.
struct SpeechTranscriptOverlay: View {
    let speechManager: SpeechInputManager
    @State private var displayText = ""
    @State private var isActive = false

    private let timer = Timer.publish(every: 0.2, on: .main, in: .common).autoconnect()

    var body: some View {
        Group {
            if isActive && !displayText.isEmpty {
                Text(displayText)
                    .font(.system(size: 11, weight: .regular, design: .monospaced))
                    .foregroundColor(.green)
                    .lineLimit(4)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.horizontal, 10)
                    .padding(.vertical, 8)
                    .background(Color.black.opacity(0.7))
            }
        }
        .onReceive(timer) { _ in
            let recording = speechManager.isRecording
            let transcript = speechManager.transcript
            if recording != isActive {
                isActive = recording
            }
            if transcript != displayText {
                displayText = transcript
            }
        }
    }
}

